// ============================================================
//  AWS Cloud Practitioner (CLF-C02) — Question Bank + Flashcards
//  223 practice questions · 135 flashcards
//  ids are stable (never reuse a retired id); section = COURSES.clf section id
// ============================================================

const FLASHCARDS = [
  { id: "clf-c-001", term: "EC2", definition: "Elastic Compute Cloud: virtual servers you rent by the second or hour. Remember: you manage the operating system and patches; AWS manages the physical hardware.", category: "compute", section: "clf-05" },
  { id: "clf-c-002", term: "Lambda", definition: "Serverless functions that run code in response to events. You pay only for requests and compute time. Remember: each run can last at most 15 minutes.", category: "compute", section: "clf-10" },
  { id: "clf-c-003", term: "Elastic Beanstalk", definition: "Platform as a service: upload your code and Beanstalk handles capacity, load balancing, scaling and health monitoring. Remember: Beanstalk itself is free; you pay for the underlying resources.", category: "compute", section: "clf-11" },
  { id: "clf-c-004", term: "ECS", definition: "Elastic Container Service: AWS's own service to run Docker containers. Run them on EC2 instances you manage, or on Fargate with no servers to manage.", category: "compute", section: "clf-10" },
  { id: "clf-c-005", term: "EKS", definition: "Elastic Kubernetes Service: managed Kubernetes for running containers. Remember: pick it when a scenario mentions Kubernetes or moving existing Kubernetes workloads to AWS.", category: "compute", section: "clf-10" },
  { id: "clf-c-006", term: "Fargate", definition: "Serverless compute engine for containers on ECS or EKS. You set CPU and memory; AWS runs the containers with no servers or clusters to manage.", category: "compute", section: "clf-10" },
  { id: "clf-c-007", term: "Lightsail", definition: "Simple virtual servers, databases and networking at a low, predictable monthly price. Remember: for users with little cloud experience who want a quick website or app.", category: "compute", section: "clf-10" },
  { id: "clf-c-008", term: "Auto Scaling Group (ASG)", definition: "Adds or removes EC2 instances automatically to match demand, keeps a minimum number running, and replaces unhealthy ones. Remember: this is elasticity, paying only for capacity you need.", category: "compute", section: "clf-07" },
  { id: "clf-c-009", term: "Elastic Load Balancer (ELB)", definition: "Spreads incoming traffic across healthy targets in multiple Availability Zones and runs health checks. Types: Application for HTTP, Network for TCP and UDP, Gateway for security appliances.", category: "compute", section: "clf-07" },
  { id: "clf-c-010", term: "AMI", definition: "Amazon Machine Image: a template of the operating system, software and settings used to launch EC2 instances. An AMI belongs to one Region but can be copied to others.", category: "compute", section: "clf-06" },
  { id: "clf-c-011", term: "EC2 Instance Store", definition: "High-performance disk physically attached to the host server. Data is lost when the instance stops or terminates. Remember: for caches and scratch data, never for data you must keep.", category: "storage", section: "clf-06" },
  { id: "clf-c-012", term: "EC2 Instance Types", definition: "Families tuned to workloads: general purpose, compute optimized for heavy processing, memory optimized for large in-memory datasets, and storage optimized for fast local disk access.", category: "compute", section: "clf-05" },
  { id: "clf-c-013", term: "AWS Batch", definition: "Fully managed batch processing at any scale. Batch queues your jobs and launches the right EC2, Spot or Fargate capacity. Remember: unlike Lambda, jobs have no 15-minute limit.", category: "compute", section: "clf-10" },
  { id: "clf-c-014", term: "AWS Outposts", definition: "Racks of AWS-managed hardware installed in your own data center to run AWS services on premises. Remember: you become responsible for the physical security of the rack.", category: "compute", section: "clf-12" },
  { id: "clf-c-015", term: "S3", definition: "Simple Storage Service: object storage in buckets with virtually unlimited capacity and eleven nines of durability. Remember: new objects are encrypted by default with SSE-S3.", category: "storage", section: "clf-08" },
  { id: "clf-c-016", term: "S3 Glacier storage classes", definition: "Low-cost archive classes. Instant Retrieval returns data in milliseconds, Flexible Retrieval in minutes to 12 hours, and Deep Archive is cheapest but slowest. Each has a minimum storage duration.", category: "storage", section: "clf-08" },
  { id: "clf-c-017", term: "S3 Intelligent-Tiering", definition: "Automatically moves each object between access tiers based on how often it is used. Small monthly monitoring fee, no retrieval fees. Remember: best when access patterns are unknown.", category: "storage", section: "clf-08" },
  { id: "clf-c-018", term: "EBS", definition: "Elastic Block Store: a network drive for EC2 that keeps data after the instance stops. Locked to one Availability Zone and usually attached to one instance at a time.", category: "storage", section: "clf-06" },
  { id: "clf-c-019", term: "EFS", definition: "Elastic File System: managed shared file system that many Linux instances can mount at once, across Availability Zones. Grows and shrinks automatically; you pay for storage used.", category: "storage", section: "clf-06" },
  { id: "clf-c-020", term: "Storage Gateway", definition: "Hybrid service that gives on-premises servers access to cloud storage backed by S3, using file, volume or tape gateways. Remember: hybrid cloud storage means Storage Gateway.", category: "storage", section: "clf-08" },
  { id: "clf-c-021", term: "AWS Backup", definition: "Fully managed service to centrally schedule and automate backups of EC2, EBS, RDS, DynamoDB, EFS and more, including cross-Region and cross-account copies. Remember: one central backup policy.", category: "storage", section: "clf-20" },
  { id: "clf-c-022", term: "EBS Snapshots", definition: "Point-in-time, incremental backups of an EBS volume. Copy them across Availability Zones or Regions to restore or move volumes. Remember: Recycle Bin can recover snapshots deleted by mistake.", category: "storage", section: "clf-06" },
  { id: "clf-c-023", term: "S3 Standard-IA", definition: "Infrequent Access: lower storage price than S3 Standard, but a per gigabyte retrieval fee. Data is kept across multiple AZs. Remember: good for backups and disaster recovery copies.", category: "storage", section: "clf-08" },
  { id: "clf-c-024", term: "S3 One Zone-IA", definition: "Like Standard-IA but kept in one Availability Zone, so it costs 20 percent less, and data is lost if that zone is destroyed. Remember: for re-creatable data.", category: "storage", section: "clf-08" },
  { id: "clf-c-025", term: "S3 Glacier Deep Archive", definition: "Cheapest S3 storage class, for data kept for years. Standard retrieval within 12 hours, bulk within 48 hours, minimum storage 180 days. Remember: long-term compliance archives.", category: "storage", section: "clf-08" },
  { id: "clf-c-026", term: "S3 Versioning", definition: "Keeps every version of an object in a bucket, protecting against accidental deletes and overwrites and allowing easy rollback. Enabled per bucket; once on, it can only be suspended.", category: "storage", section: "clf-08" },
  { id: "clf-c-027", term: "FSx", definition: "Fully managed third-party file systems. Remember: FSx for Windows File Server for Windows shares, FSx for Lustre for high-performance computing. NetApp ONTAP and OpenZFS also exist.", category: "storage", section: "clf-06" },
  { id: "clf-c-028", term: "RDS", definition: "Relational Database Service: managed SQL databases like MySQL, PostgreSQL, MariaDB, Oracle and SQL Server. AWS handles patching, backups and Multi-AZ failover; you do not manage the server.", category: "database", section: "clf-09" },
  { id: "clf-c-029", term: "Aurora", definition: "AWS's cloud-native relational database, compatible with MySQL and PostgreSQL. Storage grows automatically and keeps six copies across three AZs. Remember: faster than standard RDS engines, but costs more.", category: "database", section: "clf-09" },
  { id: "clf-c-030", term: "DynamoDB", definition: "Fully managed, serverless NoSQL key-value database with single-digit millisecond latency at any scale. Remember: Global Tables replicate across Regions; DAX adds an in-memory cache.", category: "database", section: "clf-09" },
  { id: "clf-c-031", term: "ElastiCache", definition: "Managed in-memory cache using Valkey, Redis OSS or Memcached, with sub-millisecond latency. Remember: reduces load on databases for read-heavy workloads.", category: "database", section: "clf-09" },
  { id: "clf-c-032", term: "Redshift", definition: "Data warehouse for analytics and business intelligence on petabytes of data, using columnar storage. Remember: analytics and reporting, known as OLAP, means Redshift, not RDS.", category: "database", section: "clf-09" },
  { id: "clf-c-033", term: "Neptune", definition: "Fully managed graph database for highly connected data such as social networks, recommendation engines and fraud detection.", category: "database", section: "clf-09" },
  { id: "clf-c-034", term: "DMS", definition: "Database Migration Service: migrates databases to AWS while the source stays fully operational. Handles same-engine and different-engine moves, with schema conversion for different engines.", category: "database", section: "clf-09" },
  { id: "clf-c-035", term: "DocumentDB", definition: "Fully managed document database compatible with MongoDB. Remember: think of it as the Aurora of MongoDB, with storage that grows automatically across three AZs.", category: "database", section: "clf-09" },
  { id: "clf-c-036", term: "Athena", definition: "Serverless service to query data in S3 with standard SQL, paying per amount of data scanned. Remember: ad hoc SQL queries on S3 with no servers means Athena.", category: "database", section: "clf-09" },
  { id: "clf-c-037", term: "EMR", definition: "Elastic MapReduce: managed big data clusters running Hadoop, Spark and similar frameworks on EC2. Remember: when a scenario says Hadoop or Spark, think EMR.", category: "database", section: "clf-09" },
  { id: "clf-c-038", term: "AWS Glue", definition: "Serverless extract, transform and load service that prepares data for analytics. Its Data Catalog stores table definitions used by Athena, Redshift and EMR. Remember: ETL means Glue.", category: "database", section: "clf-09" },
  { id: "clf-c-039", term: "VPC", definition: "Virtual Private Cloud: your own logically isolated network in an AWS Region, where you control IP ranges, subnets, route tables and gateways.", category: "network", section: "clf-15" },
  { id: "clf-c-040", term: "Subnet", definition: "A range of IP addresses inside a VPC, tied to one Availability Zone. Public subnets route to an internet gateway; private subnets do not.", category: "network", section: "clf-15" },
  { id: "clf-c-041", term: "Internet Gateway", definition: "Lets resources in a VPC reach the internet and be reached from it. Remember: a subnet is public when its route table points to an internet gateway.", category: "network", section: "clf-15" },
  { id: "clf-c-042", term: "NAT Gateway", definition: "AWS-managed service that lets private subnet instances reach the internet for updates, while blocking connections started from the internet. Classic zonal NAT gateways sit in a public subnet.", category: "network", section: "clf-15" },
  { id: "clf-c-043", term: "Route 53", definition: "Managed DNS service that turns domain names into IP addresses, registers domains, and routes users with policies like latency, weighted, geolocation and failover.", category: "network", section: "clf-12" },
  { id: "clf-c-044", term: "CloudFront", definition: "Content delivery network that caches content at edge locations worldwide for lower latency. Remember: also adds security, with built-in Shield Standard and optional WAF.", category: "network", section: "clf-12" },
  { id: "clf-c-045", term: "Direct Connect", definition: "Dedicated private connection from your data center to AWS that avoids the internet. Consistent performance, but takes weeks or more to set up and is not encrypted by default.", category: "network", section: "clf-15" },
  { id: "clf-c-046", term: "API Gateway", definition: "Fully managed service to create, publish and secure REST, HTTP and WebSocket APIs at any scale. Remember: the classic serverless pattern is API Gateway in front of Lambda.", category: "network", section: "clf-10" },
  { id: "clf-c-047", term: "Global Accelerator", definition: "Sends users over the AWS global network to your application through two static anycast IP addresses, improving performance and failover. Remember: unlike CloudFront, it does no caching.", category: "network", section: "clf-12" },
  { id: "clf-c-048", term: "VPC Peering", definition: "Privately connects two VPCs over the AWS network. Not transitive: peering A with B and B with C does not connect A with C. IP ranges must not overlap.", category: "network", section: "clf-15" },
  { id: "clf-c-049", term: "Transit Gateway", definition: "Hub that connects thousands of VPCs and on-premises networks in one hub-and-spoke design. Remember: replaces a complex mesh of VPC peering connections.", category: "network", section: "clf-15" },
  { id: "clf-c-050", term: "Site-to-Site VPN", definition: "Encrypted connection between your on-premises network and a VPC over the public internet. Quick to set up, but performance varies with internet conditions.", category: "network", section: "clf-15" },
  { id: "clf-c-051", term: "PrivateLink", definition: "Privately connects your VPC to AWS services, other VPCs or partner SaaS services without the internet, NAT or peering. Remember: most secure way to expose a service to many VPCs.", category: "network", section: "clf-15" },
  { id: "clf-c-052", term: "Elastic IP", definition: "A fixed public IPv4 address that stays yours until you release it and can be moved between instances. Remember: every public IPv4 address is billed hourly since 2024.", category: "network", section: "clf-15" },
  { id: "clf-c-053", term: "IAM", definition: "Identity and Access Management: a global, free service that controls who can sign in and what they can do, using users, groups, roles and policies.", category: "security", section: "clf-04" },
  { id: "clf-c-054", term: "IAM Policy", definition: "A JSON document that allows or denies actions on AWS resources, attached to users, groups or roles. Remember: an explicit deny always overrides an allow.", category: "security", section: "clf-04" },
  { id: "clf-c-055", term: "IAM Role", definition: "An identity that AWS services, applications or users assume to get temporary credentials. Remember: give an EC2 instance a role instead of storing access keys on it.", category: "security", section: "clf-04" },
  { id: "clf-c-056", term: "MFA", definition: "Multi-factor authentication: your password plus something you have, like an authenticator app, passkey or hardware security key. Remember: always protect the root user with MFA.", category: "security", section: "clf-04" },
  { id: "clf-c-057", term: "KMS", definition: "Key Management Service: create and control encryption keys used by most AWS services. AWS manages the hardware, and every key use is logged in CloudTrail.", category: "security", section: "clf-16" },
  { id: "clf-c-058", term: "CloudTrail", definition: "Records API calls and account activity: who did what, when and from where. Remember: auditing and governance; 90 days of event history are on by default.", category: "security", section: "clf-14" },
  { id: "clf-c-059", term: "GuardDuty", definition: "Intelligent threat detection that uses machine learning on CloudTrail events, VPC Flow Logs, DNS logs and more. Remember: spots threats like compromised credentials and crypto mining.", category: "security", section: "clf-16" },
  { id: "clf-c-060", term: "Security Group", definition: "Virtual firewall around an EC2 instance with allow rules only. Stateful: return traffic is automatically allowed. Remember: to block a specific IP address, use a network ACL.", category: "security", section: "clf-05" },
  { id: "clf-c-061", term: "NACL", definition: "Network access control list: a subnet-level firewall with both allow and deny rules. Stateless: return traffic must be allowed explicitly. Rules are evaluated in number order.", category: "security", section: "clf-15" },
  { id: "clf-c-062", term: "WAF", definition: "Web Application Firewall: filters layer 7 web requests to block SQL injection, cross-site scripting and bad IPs. Deploy it on CloudFront, Application Load Balancer or API Gateway.", category: "security", section: "clf-16" },
  { id: "clf-c-063", term: "Shield", definition: "DDoS protection. Shield Standard is free and automatic for every customer. Shield Advanced is paid, adding a round-the-clock response team and protection from scaling charges during attacks.", category: "security", section: "clf-16" },
  { id: "clf-c-064", term: "Inspector", definition: "Automated vulnerability management that continuously scans EC2 instances, container images in ECR and Lambda functions for software vulnerabilities and unintended network exposure.", category: "security", section: "clf-16" },
  { id: "clf-c-065", term: "AWS Config", definition: "Records resource configurations and their changes over time, and checks them against compliance rules. Remember: answers what did this resource look like last week, and is it compliant?", category: "security", section: "clf-16" },
  { id: "clf-c-066", term: "Artifact", definition: "Self-service portal for AWS compliance reports like SOC, PCI and ISO, and agreements like the HIPAA BAA. Remember: evidence for your auditors.", category: "security", section: "clf-16" },
  { id: "clf-c-067", term: "Shared Responsibility Model", definition: "AWS handles security of the cloud: hardware, facilities and global network. You handle security in the cloud: your data, IAM, configuration and guest operating system patching.", category: "security", section: "clf-03" },
  { id: "clf-c-068", term: "Principle of Least Privilege", definition: "Grant only the permissions needed for a task, nothing more. Remember: start small and add permissions when required; IAM Access Advisor shows permissions that go unused.", category: "security", section: "clf-04" },
  { id: "clf-c-069", term: "IAM Identity Center", definition: "Formerly AWS Single Sign-On: one login to all accounts in your AWS Organization and to business apps. Remember: the recommended way to give workforce users multi-account access.", category: "security", section: "clf-19" },
  { id: "clf-c-070", term: "Macie", definition: "Uses machine learning and pattern matching to discover and protect sensitive data, such as personal information, stored in S3.", category: "security", section: "clf-16" },
  { id: "clf-c-071", term: "CloudHSM", definition: "Dedicated, single-tenant hardware security modules in AWS. AWS maintains the hardware, but only you control the keys. Remember: for strict compliance needing customer-managed key hardware.", category: "security", section: "clf-16" },
  { id: "clf-c-072", term: "ACM", definition: "AWS Certificate Manager: provisions, manages and auto-renews TLS certificates for HTTPS. Public certificates used with load balancers, CloudFront or API Gateway are free.", category: "security", section: "clf-16" },
  { id: "clf-c-073", term: "Secrets Manager", definition: "Stores secrets like database passwords and API keys, with automatic rotation and native RDS integration. Remember: if a question says rotate secrets automatically, choose Secrets Manager.", category: "security", section: "clf-16" },
  { id: "clf-c-074", term: "Security Hub", definition: "Central view that collects, correlates and prioritizes security findings from GuardDuty, Inspector, Macie and partner tools across accounts. Remember: automated best-practice checks now run in Security Hub CSPM.", category: "security", section: "clf-16" },
  { id: "clf-c-075", term: "Service Control Policy (SCP)", definition: "Guardrails in AWS Organizations that set the maximum permissions for member accounts. Remember: SCPs never grant access, and they do not restrict the management account.", category: "security", section: "clf-18" },
  { id: "clf-c-076", term: "Detective", definition: "Investigates the root cause of security findings by building visual graphs from logs like CloudTrail and VPC Flow Logs. Remember: GuardDuty detects, Detective investigates.", category: "security", section: "clf-16" },
  { id: "clf-c-077", term: "Free Tier", definition: "New accounts since July 2025 get a Free plan: up to 200 dollars in credits, lasting up to six months. Always Free offers, like monthly Lambda requests, continue.", category: "billing", section: "clf-01" },
  { id: "clf-c-078", term: "On-Demand Pricing", definition: "Pay by the second or hour with no commitment or upfront payment. Highest hourly price. Remember: best for short, unpredictable workloads that must not be interrupted.", category: "billing", section: "clf-05" },
  { id: "clf-c-079", term: "Reserved Instances", definition: "Commit to a specific instance type and Region for 1 or 3 years to save up to 72 percent. Remember: for steady, predictable workloads like a database.", category: "billing", section: "clf-05" },
  { id: "clf-c-080", term: "Savings Plans", definition: "Commit to a steady dollar-per-hour spend for 1 or 3 years to save up to 72 percent. Remember: Compute Savings Plans also cover Fargate and Lambda.", category: "billing", section: "clf-18" },
  { id: "clf-c-081", term: "Spot Instances", definition: "Spare EC2 capacity at up to 90 percent off, but AWS can reclaim it with a two-minute warning. Remember: only for fault-tolerant work like batch jobs, never databases.", category: "billing", section: "clf-05" },
  { id: "clf-c-082", term: "Dedicated Hosts", definition: "An entire physical server dedicated to you, with visibility of sockets and cores. Remember: for bring-your-own server-bound software licenses and strict compliance; the most expensive option.", category: "billing", section: "clf-05" },
  { id: "clf-c-083", term: "Cost Explorer", definition: "Visualize and analyze your past AWS costs and usage, and forecast future spend. Remember: it also recommends Savings Plans.", category: "billing", section: "clf-18" },
  { id: "clf-c-084", term: "AWS Budgets", definition: "Set custom cost, usage or reservation budgets and get alerts when actual or forecasted spend crosses a threshold. Remember: Budgets alerts, Cost Explorer analyzes.", category: "billing", section: "clf-18" },
  { id: "clf-c-085", term: "Pricing Calculator", definition: "Free tool to estimate the monthly cost of an architecture before you build it. Remember: estimating future costs is Pricing Calculator; analyzing past costs is Cost Explorer.", category: "billing", section: "clf-18" },
  { id: "clf-c-086", term: "Trusted Advisor", definition: "Checks your account for cost, performance, security, fault tolerance, service limits and operations. Remember: Basic gets core checks only; all checks need Business Support Plus, formerly Business, or higher.", category: "billing", section: "clf-18" },
  { id: "clf-c-087", term: "Consolidated Billing", definition: "One bill for all accounts in AWS Organizations. Usage is combined for volume pricing discounts, and Reserved Instance and Savings Plans discounts can be shared.", category: "billing", section: "clf-18" },
  { id: "clf-c-088", term: "TAM", definition: "Technical Account Manager: a designated AWS technical expert who proactively guides your architecture and operations. Remember: a designated TAM comes with Enterprise Support.", category: "billing", section: "clf-18" },
  { id: "clf-c-089", term: "AWS Organizations", definition: "Manage many AWS accounts centrally: group them into organizational units, apply service control policies, and get consolidated billing. Remember: multi-account governance.", category: "billing", section: "clf-18" },
  { id: "clf-c-090", term: "Cost and Usage Report (CUR)", definition: "The most detailed billing data: line items for every charge, delivered to an S3 bucket for analysis with tools like Athena or Redshift.", category: "billing", section: "clf-18" },
  { id: "clf-c-091", term: "Compute Optimizer", definition: "Uses machine learning on your usage metrics to recommend right-sized EC2 instances, Auto Scaling groups, EBS volumes, Lambda functions and more. Remember: right-sizing to cut cost.", category: "billing", section: "clf-18" },
  { id: "clf-c-092", term: "AWS Marketplace", definition: "Digital catalog to find, buy and deploy third-party software, data and services that run on AWS, charged through your AWS bill.", category: "billing", section: "clf-21" },
  { id: "clf-c-093", term: "SQS", definition: "Simple Queue Service: fully managed message queue that decouples application parts; consumers poll for messages. Remember: to decouple or buffer work between components, choose SQS.", category: "compute", section: "clf-13" },
  { id: "clf-c-094", term: "SNS", definition: "Simple Notification Service: publish-subscribe messaging where one message fans out to many subscribers such as email, SMS, Lambda and SQS queues.", category: "compute", section: "clf-13" },
  { id: "clf-c-095", term: "EventBridge", definition: "Serverless event bus that reacts to events from AWS services, SaaS apps or your own code, and runs scheduled jobs. Remember: formerly CloudWatch Events.", category: "compute", section: "clf-14" },
  { id: "clf-c-096", term: "Step Functions", definition: "Orchestrates Lambda functions and other AWS services into serverless visual workflows, with retries, branching, parallel steps and human approval steps.", category: "compute", section: "clf-20" },
  { id: "clf-c-097", term: "SES", definition: "Simple Email Service: send transactional, marketing and bulk email at scale, and receive email. Remember: the answer when an application needs to send email.", category: "compute", section: "clf-20" },
  { id: "clf-c-098", term: "CloudFormation", definition: "Infrastructure as code: describe AWS resources in JSON or YAML templates and CloudFormation creates them in the right order. Remember: repeatable environments across Regions and accounts.", category: "compute", section: "clf-11" },
  { id: "clf-c-099", term: "Systems Manager", definition: "Operations hub for EC2 and on-premises servers. Patch Manager automates patching, and Run Command runs scripts across a whole fleet. Servers need the SSM Agent installed.", category: "compute", section: "clf-11" },
  { id: "clf-c-100", term: "AWS Health Dashboard", definition: "Shows the health of AWS services, plus a personalized view of events affecting your resources, like scheduled maintenance. Remember: formerly Personal Health Dashboard.", category: "compute", section: "clf-14" },
  { id: "clf-c-101", term: "Amazon Rekognition", definition: "Finds objects, people, text, scenes, and unsafe content in images and videos, and performs face analysis and face search. Think: computer vision as a service.", category: "compute", section: "clf-17" },
  { id: "clf-c-102", term: "Amazon Transcribe", definition: "Converts speech to text automatically, for example subtitles or call transcripts. It can also redact personal information and handle multiple languages.", category: "compute", section: "clf-17" },
  { id: "clf-c-103", term: "Amazon Polly", definition: "The opposite of Transcribe: turns text into lifelike speech, so applications can talk. Great for audio versions of articles and voice prompts.", category: "compute", section: "clf-17" },
  { id: "clf-c-104", term: "Amazon Comprehend", definition: "Natural language processing service. Reads text to find sentiment, key phrases, entities, language, and topics, for example analyzing customer reviews or emails.", category: "compute", section: "clf-17" },
  { id: "clf-c-105", term: "Amazon SageMaker AI", definition: "Fully managed service for data scientists and developers to build, train, and deploy their own custom machine learning models.", category: "compute", section: "clf-17" },
  { id: "clf-c-106", term: "Amazon Personalize", definition: "Builds real-time personalized product recommendations using the same technology as Amazon.com, with no machine learning expertise needed.", category: "compute", section: "clf-17" },
  { id: "clf-c-107", term: "Infrastructure as a Service (IaaS)", definition: "You rent the building blocks: servers, networking, and storage, and you manage the operating system and software. Example: Amazon EC2.", category: "compute", section: "clf-03" },
  { id: "clf-c-108", term: "Platform as a Service (PaaS)", definition: "The provider manages servers and operating systems; you just deploy your application code and data. Example: AWS Elastic Beanstalk.", category: "compute", section: "clf-03" },
  { id: "clf-c-109", term: "Software as a Service (SaaS)", definition: "A complete application that the provider runs and manages; you simply sign in and use it. Examples: Gmail, Dropbox, and Zoom.", category: "compute", section: "clf-03" },
  { id: "clf-c-110", term: "AWS Region", definition: "A separate geographic area, such as Frankfurt or Tokyo, made of multiple Availability Zones. Choose one by compliance, latency, service availability, and price.", category: "network", section: "clf-03" },
  { id: "clf-c-111", term: "Availability Zone (AZ)", definition: "One or more discrete data centers with redundant power and networking, isolated from other zones in the same Region but linked by low-latency connections.", category: "network", section: "clf-03" },
  { id: "clf-c-112", term: "Vertical Scaling", definition: "Scale up: make one instance bigger, for example from a large to an extra large instance type. Common for databases, but it has a hardware limit.", category: "compute", section: "clf-07" },
  { id: "clf-c-113", term: "Horizontal Scaling", definition: "Scale out: add more instances to share the load, and scale in by removing them. This is what Auto Scaling Groups do for distributed systems.", category: "compute", section: "clf-07" },
  { id: "clf-c-114", term: "Application Load Balancer (ALB)", definition: "Layer 7 load balancer for HTTP and HTTPS traffic. Can route requests by URL path or host name to different target groups.", category: "network", section: "clf-07" },
  { id: "clf-c-115", term: "Network Load Balancer (NLB)", definition: "Layer 4 load balancer for TCP and UDP traffic. Handles millions of requests per second with ultra-low latency and supports static IP addresses.", category: "network", section: "clf-07" },
  { id: "clf-c-116", term: "Well-Architected Framework", definition: "AWS best-practice guide built on six pillars: operational excellence, security, reliability, performance efficiency, cost optimization, and sustainability.", category: "compute", section: "clf-21" },
  { id: "clf-c-117", term: "Cloud Adoption Framework (CAF)", definition: "AWS guidance for digital transformation, organized into six perspectives: business, people, governance, platform, security, and operations.", category: "billing", section: "clf-21" },
  { id: "clf-c-118", term: "AWS re:Post", definition: "Free community question and answer site for AWS that replaced the old AWS Forums. Community experts and AWS staff answer technical questions.", category: "billing", section: "clf-21" },
  { id: "clf-c-119", term: "Customer Carbon Footprint Tool", definition: "Shows the estimated carbon emissions from your AWS usage and how they change over time. Supports the sustainability pillar.", category: "billing", section: "clf-21" },
  { id: "clf-c-120", term: "Amazon Kinesis", definition: "Collects, processes, and analyzes streaming data in real time, such as clickstreams, application logs, and IoT sensor readings.", category: "compute", section: "clf-13" },
  { id: "clf-c-121", term: "Amazon MQ", definition: "Managed message broker for RabbitMQ and ActiveMQ. Use it when migrating on-premises apps that rely on open protocols like AMQP or MQTT.", category: "compute", section: "clf-13" },
  { id: "clf-c-122", term: "Application Decoupling", definition: "Placing a queue, topic, or stream between application parts so each can scale or fail independently. Examples: SQS queues, SNS topics, and Kinesis streams.", category: "compute", section: "clf-13" },
  { id: "clf-c-123", term: "AWS CDK", definition: "Cloud Development Kit: define infrastructure in familiar programming languages like Python or TypeScript. The code is converted into a CloudFormation template.", category: "compute", section: "clf-11" },
  { id: "clf-c-124", term: "SSM Session Manager", definition: "Opens a secure shell on EC2 and on-premises servers without SSH keys, a bastion host, or an open port 22. Sessions can be logged.", category: "security", section: "clf-11" },
  { id: "clf-c-125", term: "SSM Parameter Store", definition: "Secure, serverless storage for configuration values and secrets, such as database connection strings, optionally encrypted with KMS and versioned.", category: "security", section: "clf-11" },
  { id: "clf-c-126", term: "AWS STS", definition: "Security Token Service: issues temporary, limited-privilege credentials, for example when a user or service assumes an IAM role.", category: "security", section: "clf-19" },
  { id: "clf-c-127", term: "Amazon Cognito", definition: "Identity for your web and mobile app users. Handles sign-up and sign-in for millions of users, including login with Google or Facebook.", category: "security", section: "clf-19" },
  { id: "clf-c-128", term: "AWS Directory Service", definition: "Runs Microsoft Active Directory on AWS. Options: AWS Managed Microsoft AD, AD Connector to proxy to on-premises AD, and Simple AD.", category: "security", section: "clf-19" },
  { id: "clf-c-129", term: "AWS Local Zones", definition: "Extensions of a Region placed in large metro areas, bringing compute, storage, and databases closer to users for single-digit millisecond latency.", category: "network", section: "clf-12" },
  { id: "clf-c-130", term: "AWS Wavelength", definition: "AWS infrastructure embedded inside telecom 5G networks, giving mobile devices ultra-low latency. Think: connected cars, live video, and augmented reality.", category: "network", section: "clf-12" },
  { id: "clf-c-131", term: "CloudWatch Metrics and Alarms", definition: "CloudWatch Metrics track numbers over time, like CPU utilization. Alarms watch a metric and notify through SNS or trigger actions like Auto Scaling.", category: "compute", section: "clf-14" },
  { id: "clf-c-132", term: "CloudWatch Logs", definition: "Collects, stores, and searches log files from applications, Lambda, EC2 with the CloudWatch agent, and on-premises servers. Retention is configurable.", category: "compute", section: "clf-14" },
  { id: "clf-c-133", term: "AWS X-Ray", definition: "Traces requests as they travel through distributed applications, showing a service map, so you can find bottlenecks and errors.", category: "compute", section: "clf-14" },
  { id: "clf-c-134", term: "AWS Elastic Disaster Recovery", definition: "Continuously replicates physical, virtual, and cloud servers into AWS, so you can recover them quickly, within minutes, after a disaster.", category: "compute", section: "clf-20" },
  { id: "clf-c-135", term: "AWS Fault Injection Service (FIS)", definition: "Runs controlled chaos engineering experiments, like stopping instances or adding CPU stress, to test how resilient a workload really is.", category: "compute", section: "clf-20" },
];

const QUESTIONS = [
  { id: "clf-q-001", question: "A startup does not want to buy servers before it knows whether its product will succeed. It prefers to pay each month only for the computing resources it actually uses. Which benefit of the AWS Cloud does this describe?", options: ["Benefit from massive economies of scale","Trade fixed expense for variable expense","Go global in minutes","Increase speed and agility"], answer: 1, explanation: "Paying only for what you consume, instead of investing in data centers and servers upfront, is trading fixed expense, also called capital expense, for variable expense. Economies of scale is tempting, but that benefit is about AWS lowering its prices because it operates at huge volume.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-002", question: "Which statement BEST describes elasticity in the AWS Cloud?", options: ["Data is encrypted automatically when it is stored","Workloads keep running when an Availability Zone fails","Data is copied to multiple Regions for disaster recovery","Resources scale out and in automatically to match demand"], answer: 3, explanation: "Elasticity means capacity grows when demand rises and shrinks when it falls, usually automatically with Auto Scaling, so you pay only for what you need. Staying up during an Availability Zone failure is high availability, not elasticity.", domain: "domain1", section: "clf-07" },
  { id: "clf-q-003", question: "Because AWS combines the usage of hundreds of thousands of customers, it runs its infrastructure more cheaply and has lowered its pay-as-you-go prices many times. Which benefit of cloud computing is this?", options: ["Trade fixed expense for variable expense","Increase speed and agility","Benefit from massive economies of scale","Stop guessing capacity"], answer: 2, explanation: "Economies of scale: AWS buys and operates at enormous volume and passes the savings on as lower prices. Trading fixed for variable expense is related but different. It describes how you pay, only for what you use, rather than why the unit price is low.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-004", question: "Which statement BEST describes the AWS Well-Architected Framework?", options: ["A service that automatically fixes misconfigured resources","A set of best practices organized into six pillars","A tool that estimates the monthly cost of a workload","A set of compliance reports that AWS gives to auditors"], answer: 1, explanation: "The Well-Architected Framework is guidance, not a service: best practices and design principles across six pillars. They are Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability. Cost estimates come from the Pricing Calculator, and compliance reports come from AWS Artifact.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-005", question: "A US gaming company wants to launch game servers in Asia and Europe next week so that players there get lower latency. It does not want to build any data centers. Which benefit of the AWS Cloud does this describe?", options: ["Go global in minutes","Increase speed and agility","Benefit from massive economies of scale","Stop guessing capacity"], answer: 0, explanation: "Go global in minutes means using existing AWS Regions around the world to deploy close to your users with a few clicks. Speed and agility is tempting, but it is about making resources available to developers quickly, not about worldwide reach and lower latency.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-006", question: "A startup runs all of its applications on AWS and owns no servers or data centers of its own. Which cloud deployment model is this?", options: ["Hybrid cloud","Private cloud","Multi-cloud","Public cloud"], answer: 3, explanation: "Public cloud means the infrastructure is owned and operated by a cloud provider such as AWS and delivered over the internet. Hybrid would require keeping some servers on premises, and multi-cloud would mean using more than one cloud provider.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-007", question: "A company needs to choose its own operating system, install custom software, and control network settings on its servers. Which cloud service model gives the customer the MOST control over these resources?", options: ["Software as a Service (SaaS)","Platform as a Service (PaaS)","Infrastructure as a Service (IaaS)","Function as a Service (FaaS)"], answer: 2, explanation: "Infrastructure as a Service, such as Amazon EC2, provides the building blocks: servers, networking, and storage. You manage the operating system and everything above it. Platform as a Service hides the operating system, so you only manage your application and data.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-008", question: "A company wants its workload to recover automatically from infrastructure failures, and it plans to test its recovery procedures regularly. Which pillar of the AWS Well-Architected Framework covers these practices?", options: ["Security","Reliability","Performance Efficiency","Operational Excellence"], answer: 1, explanation: "Reliability is about a workload performing its intended function correctly and consistently. Its design principles include automatically recovering from failure and testing recovery procedures. Operational Excellence is tempting because it covers running operations, but recovering from failure is a Reliability principle.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-009", question: "Before moving to AWS, a company bought servers for its highest expected peak, so most sat idle, yet it still ran out of capacity when demand surprised it. Which benefit of cloud computing solves this problem?", options: ["Stop guessing capacity","Go global in minutes","Trade fixed expense for variable expense","Increase speed and agility"], answer: 0, explanation: "Stop guessing capacity: in the cloud you use as much or as little as you need and scale within minutes, so you avoid both idle servers and shortages. Trading fixed for variable expense is related, but it describes the payment model rather than matching capacity to demand.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-010", question: "A hospital runs its patient-facing website on AWS but keeps sensitive patient records in its own data center, with the two environments connected. Which cloud deployment model is this?", options: ["Public cloud","Private cloud","Hybrid cloud","Community cloud"], answer: 2, explanation: "Hybrid cloud connects on-premises infrastructure with public cloud resources, so each workload can run where it fits best. Private cloud is tempting because of the hospital's own data center, but the hospital also runs workloads on AWS.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-011", question: "A company wants to attribute cloud spending to each team, pay only for the resources it uses, and stop running idle development servers. Which pillar of the AWS Well-Architected Framework provides this guidance?", options: ["Performance Efficiency","Operational Excellence","Cost Optimization","Sustainability"], answer: 2, explanation: "Cost Optimization is about delivering business value at the lowest price. Its design principles include adopting a consumption model and analyzing and attributing expenditure. Sustainability also reduces idle resources, but its goal is lowering environmental impact, not tracking and cutting spend.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-012", question: "Gmail, Dropbox, and Zoom are complete applications that the provider runs and manages, and users simply sign in and use them. Which cloud service model is this?", options: ["Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Function as a Service (FaaS)","Software as a Service (SaaS)"], answer: 3, explanation: "Software as a Service delivers a finished product that the provider runs and manages; you just use it. Platform as a Service is tempting, but there you still build and deploy your own application code on the provider's platform.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-013", question: "With AWS Elastic Beanstalk, developers upload their application code and AWS handles capacity provisioning, load balancing, and scaling. Which cloud service model is this?", options: ["Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Software as a Service (SaaS)","Desktop as a Service (DaaS)"], answer: 1, explanation: "Platform as a Service lets you focus on your application and data while the provider manages the servers, operating system, and scaling underneath. Infrastructure as a Service, such as Amazon EC2 on its own, would leave you managing the operating system and capacity yourself.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-014", question: "Which statement BEST describes an AWS Region?", options: ["A single data center that hosts EC2 instances","A logically isolated virtual network for your resources","A geographic area containing several Availability Zones","A site that caches content close to end users"], answer: 2, explanation: "A Region is a separate geographic area, such as Frankfurt or Northern Virginia, made up of multiple isolated Availability Zones. A single data center is smaller than a Region, an isolated virtual network is a VPC, and caching close to users happens at edge locations.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-015", question: "Which statement BEST describes an Availability Zone?", options: ["One or more isolated data centers within a Region","A range of IP addresses inside a virtual private cloud","A site that caches CloudFront content near viewers","A separate geographic area, such as Frankfurt"], answer: 0, explanation: "An Availability Zone is one or more discrete data centers with redundant power, networking, and connectivity, physically separated from the other zones in its Region. A geographic area like Frankfurt is a Region, which contains several Availability Zones.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-016", question: "A media company wants its videos and images to load quickly for viewers around the world by caching copies close to them. Which part of the AWS global infrastructure does this use?", options: ["Availability Zones","Edge locations","AWS Local Zones","AWS Regions"], answer: 1, explanation: "Edge locations, also called points of presence, are used by Amazon CloudFront to cache content close to viewers for lower latency. Local Zones are tempting, but they run compute and storage near large cities rather than acting as a content cache.", domain: "domain1", section: "clf-12" },
  { id: "clf-q-017", question: "A company must keep all customer data inside Germany to meet local data residency laws. Which factor should drive its choice of AWS Region FIRST?", options: ["Compliance with legal and data governance rules","Availability of the services and features it needs","Proximity to customers to reduce latency","Pricing, which varies from Region to Region"], answer: 0, explanation: "Legal and compliance requirements come first. AWS does not move your content out of the Region you choose, so pick one in the required country. Latency, service availability, and pricing matter too, but only among Regions that already meet the legal requirement.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-018", question: "A company wants to grant least-privilege access, record who changed what and when, and protect data in transit and at rest. Which pillar of the AWS Well-Architected Framework covers these practices?", options: ["Operational Excellence","Cost Optimization","Reliability","Security"], answer: 3, explanation: "The Security pillar covers protecting data, systems, and assets. Its design principles include a strong identity foundation with least privilege, traceability, and protecting data in transit and at rest. Operational Excellence also uses logs, but to run and improve operations rather than to protect the workload.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-019", question: "A team wants to use serverless architectures, deploy to other Regions in minutes, and experiment often with new instance types so the workload keeps meeting demand as technology evolves. Which Well-Architected pillar is this?", options: ["Security","Reliability","Performance Efficiency","Cost Optimization"], answer: 2, explanation: "Performance Efficiency is about using computing resources efficiently to meet requirements as demand and technology change. Its design principles include using serverless architectures, going global in minutes, and experimenting more often. Cost Optimization is tempting, but its focus is spend, not performance.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-020", question: "A company wants to reduce the environmental impact of its workloads by maximizing server utilization and choosing Regions with lower carbon intensity. Which pillar of the AWS Well-Architected Framework covers this?", options: ["Sustainability","Cost Optimization","Operational Excellence","Reliability"], answer: 0, explanation: "The Sustainability pillar, the sixth pillar added in 2021, focuses on minimizing the environmental impact of cloud workloads, for example by maximizing utilization. Cost Optimization often removes waste too, but its goal is lower cost, not lower energy use and emissions.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-021", question: "What is the difference between scalability and elasticity?", options: ["Scalability works across Regions, while elasticity works only inside one Availability Zone","Scalability means handling more load; elasticity adds automatic scaling up and down with demand","Scalability always happens automatically, while elasticity always requires manual resizing","Scalability applies only to compute, while elasticity applies only to storage such as S3"], answer: 1, explanation: "A scalable system can grow to handle more load, by scaling up or out. Elasticity builds on that with automatic scaling, so capacity follows demand up and down and you pay only for what you use. Both apply to many services, not just compute or storage.", domain: "domain1", section: "clf-07" },
  { id: "clf-q-022", question: "A company runs its web application on EC2 instances in two Availability Zones behind a load balancer, so users can still reach it if one zone has an outage. Which cloud concept does this design provide?", options: ["Elasticity","Agility","High availability","Economies of scale"], answer: 2, explanation: "High availability means running in at least two Availability Zones so the application survives the loss of a data center. Elasticity is tempting because load balancers often pair with Auto Scaling, but elasticity is about matching capacity to demand, not surviving failures.", domain: "domain1", section: "clf-07" },
  { id: "clf-q-023", question: "A payment system uses fully redundant components so it keeps processing transactions without interruption, even when a server or disk fails. Which design characteristic does this describe?", options: ["Fault tolerance","Elasticity","Agility","Vertical scaling"], answer: 0, explanation: "Fault tolerance is the ability to keep operating without interruption when some components fail, usually through built-in redundancy. Elasticity is about adjusting capacity to demand, and vertical scaling just makes a single server bigger, which adds no redundancy.", domain: "domain1", section: "clf-07" },
  { id: "clf-q-024", question: "During its migration to AWS, a company stops running its self-hosted customer relationship management (CRM) software and moves to a SaaS CRM product instead. Which migration strategy is this?", options: ["Rehost","Refactor","Repurchase","Retain"], answer: 2, explanation: "Repurchase, sometimes called drop and shop, means replacing an application with a different product, often SaaS. Rehost would move the existing CRM unchanged onto EC2, and refactor would re-architect it with cloud-native services. Retain means leaving it where it is for now.", domain: "domain1", section: "clf-20" },
  { id: "clf-q-025", question: "A company's application must keep running if a data center fails, but all of its data must stay within a single AWS Region for compliance. What is the MOST appropriate design?", options: ["Deploy in one Availability Zone using larger EC2 instances","Deploy across two Regions located in different countries","Deploy in one Availability Zone with nightly EBS snapshots","Deploy across multiple Availability Zones in the same Region"], answer: 3, explanation: "Availability Zones are physically separate data centers within one Region, so spreading across them survives a data center failure while the data stays in the Region. Two Regions would break the compliance rule, and snapshots help recovery but do not keep the application running.", domain: "domain1", section: "clf-07" },
  { id: "clf-q-026", question: "A company's IT staff used to spend most of their time racking servers, replacing failed disks, and managing cooling. After moving to AWS, they focus on customer features instead. Which benefit of cloud computing is this?", options: ["Go global in minutes","Stop spending money maintaining data centers","Benefit from massive economies of scale","Trade fixed expense for variable expense"], answer: 1, explanation: "AWS handles the undifferentiated heavy lifting of racking, stacking, and powering servers, so your team can focus on work that sets your business apart. Economies of scale is tempting, but that benefit is about lower prices, not about freeing your staff from data center work.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-027", question: "A development team can now launch test environments in minutes instead of waiting weeks for new hardware, so it experiments more and releases features faster. Which benefit of cloud computing is this?", options: ["Benefit from massive economies of scale","Go global in minutes","Stop guessing capacity","Increase speed and agility"], answer: 3, explanation: "Speed and agility: new resources are a click away, so the time to make them available to developers drops from weeks to minutes, which makes experimenting cheap and fast. Stop guessing capacity is tempting, but it is about matching capacity to demand.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-028", question: "A solutions architect wants to review a workload against AWS best practices for all six pillars, record the answers, and get a prioritized improvement plan. Which AWS service should the architect use?", options: ["AWS Config","AWS Trusted Advisor","AWS CloudFormation","AWS Well-Architected Tool"], answer: 3, explanation: "The AWS Well-Architected Tool is a free console service that walks you through questions for each pillar and produces an improvement plan. Trusted Advisor is tempting, but it runs automated checks on your account's resources rather than a guided review of a workload.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-029", question: "A company already owns Microsoft SQL Server licenses and wants to reuse them on AWS rather than pay for new licenses. Which licensing strategy does this describe?", options: ["License-included instances","AWS Marketplace subscriptions","Bring your own license (BYOL)","Compute Savings Plans"], answer: 2, explanation: "Bring your own license reuses software licenses you already own, subject to the vendor's terms, and some licenses require EC2 Dedicated Hosts. License-included instances are tempting, but they bundle the cost of a new license into the hourly price, so the existing licenses would go unused.", domain: "domain1", section: "clf-05" },
  { id: "clf-q-030", question: "A developer creates a new database and several servers from the AWS Management Console in minutes, without contacting anyone at AWS. Which characteristic of cloud computing does this show?", options: ["On-demand self-service","Resource pooling","Measured service","Broad network access"], answer: 0, explanation: "On-demand self-service means you provision resources yourself, whenever you need them, with no human interaction with the provider. Measured service is about paying for exactly what you use, and resource pooling is about many customers securely sharing the same infrastructure.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-031", question: "A company wants to create identical test and production environments repeatedly, with every infrastructure change reviewed and version controlled like application code. What should it use?", options: ["Console wizards that launch each resource by hand","Infrastructure as code with AWS CloudFormation","Recommendations from AWS Trusted Advisor","Server clones built from Amazon Machine Images"], answer: 1, explanation: "Infrastructure as code, such as CloudFormation templates, defines resources in files that can be versioned, reviewed, and deployed again and again with the same result. Machine images are tempting, but they only copy individual servers, not the networking, databases, and other resources around them.", domain: "domain1", section: "clf-11" },
  { id: "clf-q-032", question: "An application's traffic keeps growing, so the team adds more EC2 instances behind a load balancer to share the work. What type of scaling is this?", options: ["Scaling up","Scaling in","Scaling out","Scaling down"], answer: 2, explanation: "Adding more instances is horizontal scaling, also called scaling out, and removing them is scaling in. Scaling up and down is vertical scaling, which changes the size of a single instance. Horizontal scaling is common for web tiers and distributed systems.", domain: "domain1", section: "clf-07" },
  { id: "clf-q-033", question: "A database runs on a single EC2 instance that needs more memory. The team stops it and changes the instance type from m5.large to m5.2xlarge. Which term describes this change?", options: ["Horizontal scaling","Scaling in","Elasticity","Vertical scaling"], answer: 3, explanation: "Making a single instance larger, with more CPU or memory, is vertical scaling, also called scaling up. It is common for databases but has a hardware limit. Horizontal scaling adds instances instead, and elasticity means scaling automatically with demand, which this manual change is not.", domain: "domain1", section: "clf-07" },
  { id: "clf-q-034", question: "Which statement BEST describes a private cloud?", options: ["Cloud services delivered to anyone over the public internet","Cloud infrastructure operated for a single organization","A mix of on-premises and public cloud resources","Cloud infrastructure shared by several related organizations"], answer: 1, explanation: "A private cloud is used by a single organization and is not exposed to the public, giving more control over security and sensitive data. A mix of on-premises and public cloud is hybrid cloud, and infrastructure shared by several organizations is a community cloud.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-035", question: "A company must exit its data center within three months. It plans to move its virtual machines to Amazon EC2 as quickly as possible without changing the applications. Which migration strategy is this?", options: ["Rehost","Replatform","Refactor","Retire"], answer: 0, explanation: "Rehost, or lift and shift, moves applications to AWS as they are, often with AWS Application Migration Service, and is usually the fastest option. Replatform is tempting, but it adds some optimization, such as moving a database to Amazon RDS. Refactor re-architects the application with cloud-native services.", domain: "domain1", section: "clf-20" },
  { id: "clf-q-036", question: "Which of the following is a design principle of the Operational Excellence pillar of the AWS Well-Architected Framework?", options: ["Protect data in transit and at rest","Adopt a consumption model","Automatically recover from failure","Make frequent, small, reversible changes"], answer: 3, explanation: "Operational Excellence favors frequent, small, reversible changes, safely automating where possible, and learning from operational events. Protecting data belongs to Security, a consumption model belongs to Cost Optimization, and automatic recovery from failure belongs to Reliability.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-037", question: "An online store's website sends each order directly to a processing server. When the processing server slows down, the website fails too. Which change BEST applies the principle of loose coupling?", options: ["Run both components on one larger EC2 instance","Deploy both components in a single Availability Zone","Place an Amazon SQS queue between the two components","Increase the timeout on calls from the website to the server"], answer: 2, explanation: "Loose coupling means components interact through a buffer or well-defined interface, so one can slow down or fail without breaking the other. An SQS queue holds orders until the processor is ready. Putting both on one instance does the opposite and tightens the coupling.", domain: "domain1", section: "clf-13" },
  { id: "clf-q-038", question: "A company is comparing its current costs with AWS before migrating. Which of these is a capital expenditure (CapEx)?", options: ["Buying physical servers for its own data center","Paying a monthly bill for EC2 On-Demand usage","Paying per gigabyte-month for Amazon S3 storage","Paying per request for AWS Lambda invocations"], answer: 0, explanation: "Capital expenditure is money spent upfront on physical assets, such as servers and data center equipment, before you know how much you will use them. The AWS charges listed are operational expenditure: variable, pay-as-you-go costs based on actual usage.", domain: "domain1", section: "clf-03" },
  { id: "clf-q-039", question: "A company's cloud migration is slowed because staff lack cloud skills and teams resist new ways of working. Which AWS Cloud Adoption Framework (AWS CAF) perspective focuses on training, culture, and organizational change?", options: ["Business","People","Governance","Operations"], answer: 1, explanation: "The People perspective bridges technology and business, covering culture, organizational structure, leadership, and workforce skills. Governance is tempting, but it covers program management, benefits, risk, and cloud financial management. The six perspectives are Business, People, Governance, Platform, Security, and Operations.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-040", question: "A company's traffic triples every weekday at 8 AM and drops at 6 PM, following the same pattern each week. It wants EC2 capacity added just before the morning rush, not after it starts. Which Auto Scaling approach fits BEST?", options: ["Scheduled scaling","Target tracking scaling","Manual scaling","Vertical scaling"], answer: 0, explanation: "Scheduled scaling changes an Auto Scaling group's capacity at set times, so instances are ready before a known, recurring peak. Target tracking is tempting, but it reacts to a metric such as CPU after load has already risen, so users would feel the first minutes of the rush.", domain: "domain3", section: "clf-07" },
  { id: "clf-q-041", question: "A company's cloud program must track the business benefits of its migration, manage transformation risk, and practice cloud financial management. Which AWS Cloud Adoption Framework (AWS CAF) perspective provides these capabilities?", options: ["Business","Governance","Platform","Operations"], answer: 1, explanation: "The Governance perspective orchestrates cloud initiatives while maximizing benefits and minimizing risk. Its capabilities include benefits management, risk management, and cloud financial management. The Business perspective is tempting, but it focuses on strategy, products, and making sure cloud investments drive business outcomes.", domain: "domain1", section: "clf-21" },
  { id: "clf-q-042", question: "A company runs MySQL on EC2 and spends hours each week on patching, backups, and setting up failover. Which option reduces this work with the LEAST operational overhead?", options: ["Move the database to a larger EC2 instance type","Purchase Reserved Instances for the database servers","Run the database in a single Availability Zone","Migrate the database to Amazon RDS for MySQL"], answer: 3, explanation: "Amazon RDS is a managed database service: AWS automates patching, backups, and Multi-AZ failover, so the team can focus on the application. A larger instance may improve performance and Reserved Instances lower cost, but both leave all the administration work with the team.", domain: "domain1", section: "clf-09" },
  { id: "clf-q-043", question: "A company runs a web application on Amazon EC2. Under the AWS Shared Responsibility Model, which task is the company's responsibility?", options: ["Physical security of the data center facilities","Configuring the instance's security group rules","Patching the hypervisor that hosts the instance","Maintaining the underlying network hardware"], answer: 1, explanation: "Security groups are settings the customer controls, so their rules are the customer's job. Facilities, the hypervisor, and network hardware are security OF the cloud, which AWS owns. Remember: if you can configure it, you are responsible for it.", domain: "domain2", section: "clf-05" },
  { id: "clf-q-044", question: "An EC2 instance was terminated unexpectedly. The security team must find out which IAM identity made the TerminateInstances API call, and when. Which service should they check?", options: ["Amazon CloudWatch","AWS CloudTrail","Amazon GuardDuty","AWS Config"], answer: 1, explanation: "CloudTrail records API calls in your account, including who made each call, when, and from which IP address. Think of it as a trail of footprints. CloudWatch tracks metrics and logs about performance, and AWS Config tracks how resource settings change rather than serving as the API audit log.", domain: "domain2", section: "clf-14" },
  { id: "clf-q-045", question: "A startup has just created a new AWS account. Which action should it take FIRST to secure the account?", options: ["Create access keys for the root user","Create an S3 bucket for CloudTrail logs","Enable MFA on the root user","Enable Amazon GuardDuty in every Region"], answer: 2, explanation: "The root user has unrestricted access, so protecting it with multi-factor authentication comes first. Next, create an administrative identity for daily work. Root access keys should never be created, and logging or threat detection come after the root user is locked down.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-046", question: "A small company wants protection against common network and transport layer DDoS attacks without paying anything extra. Which AWS offering provides this automatically?", options: ["Amazon GuardDuty","AWS WAF","AWS Shield Advanced","AWS Shield Standard"], answer: 3, explanation: "Shield Standard is included for every AWS customer at no extra cost and automatically defends against common layer 3 and layer 4 DDoS attacks. Shield Advanced adds more protection and a response team for a monthly fee, and WAF filters web requests and is billed by usage.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-047", question: "A new analyst only needs to read reports stored in one S3 bucket. The administrator grants read access to that bucket and nothing else. Which security principle is being applied?", options: ["Least privilege","Defense in depth","Separation of duties","Shared responsibility"], answer: 0, explanation: "Least privilege means granting only the permissions a task requires and nothing more. Defense in depth is about stacking several layers of controls, and separation of duties splits critical tasks between different people. Remember: start with minimal permissions and add more only when needed.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-048", question: "A company must block all traffic from one malicious IP address to every instance in a subnet. Which feature can explicitly DENY traffic from that address?", options: ["IAM policy","Security group","Route table","Network ACL"], answer: 3, explanation: "Network ACLs work at the subnet level and support both allow and deny rules, so they can block a specific IP address. Security groups only have allow rules and apply to individual instances. Remember: to deny an IP address, reach for the network ACL.", domain: "domain2", section: "clf-15" },
  { id: "clf-q-049", question: "An auditor asks a company for AWS's own SOC 2 and PCI DSS compliance reports. Where can the company download them on demand?", options: ["AWS Artifact","AWS Trusted Advisor","AWS Config","AWS Audit Manager"], answer: 0, explanation: "AWS Artifact is the self-service portal for downloading AWS compliance reports, such as SOC and PCI reports, and for accepting agreements like the HIPAA Business Associate Addendum. Audit Manager collects evidence about your own resource usage, not AWS's third-party audit reports.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-050", question: "An application on an EC2 instance must upload files to an S3 bucket. What is the MOST secure way to give it permission?", options: ["Store an IAM user's access keys on the instance","Save the root user's keys in a config file","Add the instance to an IAM group for S3","Attach an IAM role that allows S3 uploads"], answer: 3, explanation: "An IAM role attached to the instance supplies temporary credentials that AWS rotates automatically, so there are no keys to leak. Long-term access keys stored on disk can be stolen, root keys should never exist, and IAM groups can only contain users, not instances.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-051", question: "A company uses HTTPS so that data sent between customers' browsers and its website cannot be read if intercepted. What type of protection is this?", options: ["Encryption at rest","Encryption in transit","Envelope encryption","Server-side encryption"], answer: 1, explanation: "HTTPS uses TLS to encrypt data while it moves across the network, which is encryption in transit. Encryption at rest protects stored data, such as S3 objects or EBS volumes. Server-side encryption also protects stored data, and envelope encryption is a key management technique, not the protection HTTPS provides.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-052", question: "A company runs Amazon Linux on its EC2 instances. Who is responsible for installing security patches on the instances' operating system?", options: ["AWS, for all instances","AWS, if the instance uses an AWS-provided AMI","The customer, for every instance","AWS Support, for Enterprise Support customers"], answer: 2, explanation: "On EC2, the customer manages the guest operating system, including patches, even when the AMI comes from AWS. AWS is responsible for the physical hosts and the hypervisor. Systems Manager Patch Manager can automate patching, but running it is still the customer's job.", domain: "domain2", section: "clf-05" },
  { id: "clf-q-053", question: "Under the AWS Shared Responsibility Model, who controls physical access to the data centers that host a customer's EC2 instances?", options: ["The customer","AWS","The customer and AWS jointly","The customer's compliance auditor"], answer: 1, explanation: "Physical security of facilities, including guards, access controls, and environmental systems, is security OF the cloud, which AWS owns. Customers never get physical access to AWS data centers. Independent auditors review these controls, and their reports are available in AWS Artifact.", domain: "domain2", section: "clf-03" },
  { id: "clf-q-054", question: "A company is moving its workloads from its own data center to AWS. Which task will AWS take over from the company's in-house team?", options: ["Encrypting the company's application data","Managing IAM users and their permissions","Replacing failed servers and network hardware","Configuring security groups on instances"], answer: 2, explanation: "AWS is responsible for security OF the cloud: the hardware, networking, facilities, and virtualization layer. Encrypting data, managing IAM identities, and configuring security groups are security IN the cloud, so they remain the customer's tasks.", domain: "domain2", section: "clf-03" },
  { id: "clf-q-055", question: "A company migrates a self-managed MySQL database to Amazon RDS. Which task does AWS now handle for the company?", options: ["Creating database users and their permissions","Patching the operating system of the database host","Setting security group rules for the database","Choosing whether the database is publicly accessible"], answer: 1, explanation: "RDS is a managed service, so AWS patches the host operating system, which customers cannot even log in to. The customer still controls database users, security group rules, public accessibility, and encryption settings.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-056", question: "A developer uploads a new object to Amazon S3 without specifying any encryption settings. What happens to the object?", options: ["S3 encrypts it at rest with SSE-S3 by default","S3 stores it unencrypted until a policy is added","S3 rejects the upload with an access denied error","S3 encrypts it with a customer managed KMS key"], answer: 0, explanation: "Since 2023, S3 automatically encrypts every new object at rest with S3 managed keys, called SSE-S3, at no extra cost. Customers can choose SSE-KMS when they need more control and auditing, and choosing those settings remains the customer's responsibility.", domain: "domain2", section: "clf-08" },
  { id: "clf-q-057", question: "A company has one standalone AWS account that is not part of AWS Organizations. Its administrators are IAM users with full admin permissions. Which task still requires signing in as the root user?", options: ["Creating a new IAM user for a contractor","Launching EC2 instances in a new Region","Turning on AWS CloudTrail logging","Closing the AWS account"], answer: 3, explanation: "A few tasks need the root user even when IAM administrators exist, such as closing a standalone account, changing the root email address or password, and restoring IAM permissions after a lockout. Everyday work like creating users or launching instances should use IAM identities.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-058", question: "Why does AWS recommend against using the root user for everyday administrative tasks?", options: ["It has full access, so a compromise affects everything","It cannot be protected with multi-factor authentication","It cannot view the billing and cost management pages","Its API calls are billed at a higher rate than IAM calls"], answer: 0, explanation: "The root user has complete access to every service, resource, and billing setting, so a leaked root password could cost you the whole account. Use IAM identities with least privilege for daily work, and protect root with MFA, which it fully supports.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-059", question: "A company hires five developers who all need identical permissions. What is the MOST efficient way to manage their access while following best practices?", options: ["Attach the same policy to each user separately","Create a separate IAM role for each developer","Add them to an IAM group that has the policy","Have all five share a single IAM user login"], answer: 2, explanation: "IAM groups let you attach a policy once and every member inherits it, so adding or removing a developer is one step. Attaching policies user by user becomes error-prone, and sharing one login breaks accountability because CloudTrail can no longer tell who did what.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-060", question: "An administrator wants to place the Developers IAM group inside an Engineering IAM group so permissions flow down. What will happen?", options: ["It works, and permissions pass down to the inner group","It is not possible, because groups contain only users","It works only if both groups belong to AWS Organizations","It works only if both groups have the same policy attached"], answer: 1, explanation: "IAM groups cannot be nested: a group can contain only users, not other groups. A user can, however, belong to several groups at once and receives the combined permissions of all of them.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-061", question: "A security engineer is writing a custom IAM policy that allows read access to one S3 bucket. In which format is the policy document written?", options: ["JSON","YAML","XML","CSV"], answer: 0, explanation: "IAM policies are JSON documents. Each statement has an Effect of Allow or Deny, a list of Actions, the Resources they apply to, and optional Conditions. YAML is common in CloudFormation templates, but IAM itself stores and evaluates policies as JSON.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-062", question: "An IAM user belongs to a group whose policy allows all Amazon S3 actions. A policy attached directly to the user explicitly denies deleting S3 objects. What happens when the user tries to delete an object?", options: ["It succeeds, because group permissions take priority","It succeeds, because the allow was granted first","It succeeds only if the user signed in with MFA","It fails, because an explicit deny always wins"], answer: 3, explanation: "IAM combines every policy that applies to the user, and an explicit deny in any of them overrides any allow, wherever or whenever that allow was granted. Group permissions do not outrank user permissions, and nothing in this deny depends on MFA.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-063", question: "A company wants IAM users to prove their identity with a code from an authenticator app or a security key in addition to their password. Which feature should it enable?", options: ["An account password policy","IAM Identity Center","Multi-factor authentication","IAM Access Analyzer"], answer: 2, explanation: "Multi-factor authentication combines something you know, your password, with something you have, such as an authenticator app, a passkey, or a hardware security key. A password policy only sets rules like length and expiration, so it cannot stop a stolen password from being used.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-064", question: "An administrator wants to remove permissions that an IAM user has not used in months. Which tool shows the services the user is allowed to access and when each was last used?", options: ["IAM Access Advisor","AWS CloudTrail","IAM credentials report","AWS Trusted Advisor"], answer: 0, explanation: "IAM Access Advisor, the last accessed tab on a user, group, or role, lists the services its permissions allow and when each was last used, which makes trimming unused permissions easy. The credentials report is account-wide and covers passwords, access keys, and MFA status instead.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-065", question: "An auditor wants a single account-wide list of all IAM users showing whether each has MFA enabled and when their access keys were last rotated. Which tool provides this?", options: ["AWS Config","IAM Access Advisor","IAM credentials report","AWS Security Hub"], answer: 2, explanation: "The IAM credentials report is a downloadable account-level file listing every user and the status of their passwords, access keys, and MFA devices. Access Advisor works per identity and shows service last-used data. Config and Security Hub can flag noncompliant users but do not produce this ready-made inventory.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-066", question: "A company wants a managed service that continuously analyzes CloudTrail events, VPC Flow Logs, and DNS logs to detect threats such as compromised instances. Which service should it enable?", options: ["Amazon GuardDuty","Amazon Inspector","AWS Network Firewall","Amazon Macie"], answer: 0, explanation: "GuardDuty is intelligent threat detection. It applies machine learning, anomaly detection, and threat intelligence to CloudTrail events, VPC Flow Logs, and DNS logs, with no agents to install. Inspector scans for software vulnerabilities, and Macie finds sensitive data in S3, so neither watches for active threats.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-067", question: "A company wants automated, continuous scanning of its EC2 instances, container images in Amazon ECR, and Lambda functions for known software vulnerabilities. Which service should it use?", options: ["Amazon GuardDuty","Amazon Macie","Amazon Inspector","AWS Config"], answer: 2, explanation: "Amazon Inspector continuously scans EC2 instances, ECR container images, and Lambda functions for known software vulnerabilities and unintended network exposure. GuardDuty detects active threats from log analysis, and Macie discovers sensitive data in S3, so neither assesses software vulnerabilities.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-068", question: "A company must find out whether any of its S3 buckets contain personally identifiable information, such as credit card numbers. Which service uses machine learning to discover this data?", options: ["Amazon GuardDuty","Amazon Macie","Amazon Inspector","Amazon Detective"], answer: 1, explanation: "Macie uses machine learning and pattern matching to discover and report sensitive data, such as personally identifiable information, stored in Amazon S3. GuardDuty looks for threats and Inspector looks for vulnerabilities, but neither classifies the contents of your objects. Remember: Macie means sensitive data in S3.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-069", question: "A company needs public TLS certificates for its Application Load Balancer, at no extra cost and renewed automatically. Which service should it use?", options: ["AWS Certificate Manager","AWS CloudHSM","AWS Key Management Service","AWS Secrets Manager"], answer: 0, explanation: "AWS Certificate Manager provisions public TLS certificates at no extra cost and renews them automatically for integrated services such as Elastic Load Balancing, CloudFront, and API Gateway. KMS manages encryption keys and Secrets Manager stores credentials, but neither issues certificates.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-070", question: "A company wants to store its Amazon RDS database password securely and have it rotated automatically every 30 days. Which service is the BEST fit?", options: ["AWS Key Management Service","Systems Manager Parameter Store","AWS Identity and Access Management","AWS Secrets Manager"], answer: 3, explanation: "Secrets Manager stores secrets such as database passwords and can rotate them automatically on a schedule, with built-in support for Amazon RDS. Parameter Store can hold encrypted values but has no built-in automatic rotation, and KMS manages encryption keys, not the secrets themselves.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-071", question: "A company wants AWS to manage the encryption keys used for its EBS volumes and S3 objects, with every key use logged in CloudTrail and the LEAST operational overhead. Which service should it use?", options: ["AWS CloudHSM","AWS Key Management Service","AWS Certificate Manager","AWS Secrets Manager"], answer: 1, explanation: "AWS KMS is the fully managed service for creating and controlling encryption keys. It integrates with most services, including EBS and S3, and every key use is logged in CloudTrail. CloudHSM gives you dedicated hardware that you manage yourself, which is more work than this company needs.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-072", question: "Security groups are stateful. What does this mean for traffic to an EC2 instance?", options: ["Rules are evaluated in number order, lowest first","Responses to allowed traffic are automatically allowed","Rules can explicitly allow or deny traffic","Rules apply to every instance in the subnet"], answer: 1, explanation: "Stateful means the security group remembers allowed connections, so response traffic flows back without needing a matching rule. Numbered rule order, explicit deny rules, and subnet-wide scope are all traits of network ACLs, not security groups.", domain: "domain2", section: "clf-15" },
  { id: "clf-q-073", question: "A custom network ACL allows inbound HTTP on port 80 but has no outbound allow rules. The instance's security group allows HTTP. Why do users get no response?", options: ["The security group lacks an outbound rule for responses","The stateless network ACL blocks the return traffic","The route table does not allow traffic on port 80","The instance lacks an IAM role for replying to users"], answer: 1, explanation: "Network ACLs are stateless, so return traffic is evaluated separately and needs its own outbound rule, typically for the ephemeral port range. Security groups are stateful and allow responses automatically, and route tables direct traffic by IP address, not by port.", domain: "domain2", section: "clf-15" },
  { id: "clf-q-074", question: "A security team uses GuardDuty, Inspector, and Macie across several AWS accounts and wants one place to view, correlate, and prioritize all of their findings. Which service should it use?", options: ["AWS CloudTrail","Amazon Detective","AWS Security Hub","AWS Trusted Advisor"], answer: 2, explanation: "Security Hub aggregates, correlates, and prioritizes findings from GuardDuty, Inspector, Macie, and partner tools across accounts in a single view. Detective is for investigating the root cause of a specific finding, and Trusted Advisor gives general best practice recommendations rather than collecting security findings.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-075", question: "A company uses AWS Organizations and wants to stop every account in its Sandbox organizational unit from using services outside two approved Regions, even for account administrators. What should it use?", options: ["An IAM identity-based policy","An IAM group policy","A security group rule","A service control policy"], answer: 3, explanation: "Service control policies in AWS Organizations set the maximum permissions for every account in an organizational unit, including each account's administrators and root user. They restrict but never grant access. IAM policies live inside one account, so a local administrator could simply change them.", domain: "domain2", section: "clf-18" },
  { id: "clf-q-076", question: "An online retailer stores and processes customers' credit card numbers on AWS. Which compliance standard applies to this data?", options: ["PCI DSS","SOC 2","FedRAMP","HIPAA"], answer: 0, explanation: "PCI DSS, the Payment Card Industry Data Security Standard, applies to any organization that stores, processes, or transmits cardholder data. AWS is a PCI DSS Level 1 service provider, and its attestation is available in AWS Artifact. HIPAA covers health data, and FedRAMP covers US government workloads.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-077", question: "A US clinic plans to store patient health records on AWS. Which regulation governs how this protected health information must be handled?", options: ["PCI DSS","HIPAA","GDPR","SOC 1"], answer: 1, explanation: "HIPAA, the Health Insurance Portability and Accountability Act, governs protected health information in the United States. Customers accept the AWS Business Associate Addendum in AWS Artifact and use HIPAA eligible services. PCI DSS covers payment card data, and GDPR covers personal data of people in the EU.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-078", question: "A company based in Canada collects personal data from customers living in France and Germany. Which regulation MOST directly governs the privacy of this data?", options: ["HIPAA","PCI DSS","GDPR","FedRAMP"], answer: 2, explanation: "GDPR, the General Data Protection Regulation, protects the personal data of people in the European Union, no matter where the company processing it is located. HIPAA covers US health information, PCI DSS covers payment card data, and FedRAMP covers cloud services used by the US government.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-079", question: "A web application behind an Application Load Balancer is receiving SQL injection and cross-site scripting attempts. Which service can filter out these malicious requests?", options: ["AWS Shield Standard","Amazon GuardDuty","Security groups","AWS WAF"], answer: 3, explanation: "AWS WAF is a layer 7 web application firewall. It inspects HTTP requests to CloudFront, Application Load Balancers, and API Gateway and blocks patterns like SQL injection and cross-site scripting. Shield protects against DDoS floods, and security groups filter only by IP address, protocol, and port.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-080", question: "A company's revenue depends on its public website. It wants round-the-clock access to the AWS Shield Response Team and protection from scaling charges caused by DDoS attacks. Which option meets these needs?", options: ["AWS Shield Standard","AWS Shield Advanced","AWS WAF","AWS Firewall Manager"], answer: 1, explanation: "Shield Advanced is the paid tier. It adds round-the-clock access to the Shield Response Team, advanced attack detection, and cost protection against scaling charges caused by DDoS attacks. Shield Standard is free and automatic but has no response team or cost protection, and WAF alone only filters web requests.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-081", question: "An auditor asks how a security group's rules looked last month and whether it was compliant with company rules at that time. Which service keeps this configuration history?", options: ["AWS CloudTrail","Amazon CloudWatch","Amazon Inspector","AWS Config"], answer: 3, explanation: "AWS Config records the configuration of your resources over time and evaluates them against rules, so you can see what a resource looked like on a past date and whether it was compliant. CloudTrail shows who made each API call, but not the resulting configuration or its compliance.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-082", question: "A contractor needs access to a production account for a few hours to troubleshoot an issue. What is the MOST secure approach?", options: ["Share the root user's password and MFA code","Create an IAM user and delete it when finished","Allow them to assume a role for temporary access","Email them a new set of long-term access keys"], answer: 2, explanation: "Assuming an IAM role returns temporary credentials from the AWS Security Token Service, STS, which expire automatically. There are no long-term secrets to leak or forget to remove. A temporary IAM user still carries long-term credentials if the cleanup is missed.", domain: "domain2", section: "clf-19" },
  { id: "clf-q-083", question: "Which analogy BEST describes the AWS Shared Responsibility Model?", options: ["A landlord maintains the building; tenants lock their own units","A teacher sets the exam; students grade their own answers","A factory line where each worker builds part of one product","A buyer owns and maintains everything after the purchase"], answer: 0, explanation: "AWS is like a landlord responsible for the building: facilities, hardware, and the virtualization layer, which is security OF the cloud. The customer is like a tenant responsible for what they control inside, such as data, access, and configuration, which is security IN the cloud.", domain: "domain2", section: "clf-03" },
  { id: "clf-q-084", question: "GuardDuty has flagged suspicious activity from an EC2 instance. The security team wants to investigate the root cause using linked, visualized log data over time. Which service should it use?", options: ["AWS Security Hub","Amazon Inspector","AWS Config","Amazon Detective"], answer: 3, explanation: "Amazon Detective automatically collects log data and uses machine learning and graph visualizations to help you investigate the root cause of findings from GuardDuty and other services. Security Hub collects and prioritizes findings, but digging into what actually happened is the job of Detective.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-085", question: "A company requires every IAM user password to be at least 14 characters long and to expire every 90 days. Which feature enforces this?", options: ["IAM password policy","IAM group policy","IAM Access Analyzer","Multi-factor authentication"], answer: 0, explanation: "The account password policy sets rules for IAM user passwords, such as minimum length, required character types, expiration, and preventing reuse. MFA adds a second factor at sign-in but does not control password rules, and group policies grant permissions rather than setting password requirements.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-086", question: "A developer wants to run AWS CLI commands from a laptop as an IAM user. Which credentials does the CLI use to sign those requests?", options: ["An EC2 key pair's private key","An access key ID and secret access key","An ACM certificate and its private key","A KMS key ID and its key alias"], answer: 1, explanation: "The AWS CLI and SDKs sign every request with an access key ID and secret access key. Treat the secret key like a password and never share or commit it. EC2 key pairs are only for SSH logins to instances, and KMS keys encrypt data rather than authenticate you.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-087", question: "A company needs to review AWS API activity from eight months ago, but CloudTrail event history only shows the last 90 days. What should the company have set up in advance?", options: ["CloudWatch detailed monitoring on all instances","VPC Flow Logs for every VPC","A CloudTrail trail delivering logs to Amazon S3","An upgrade to the Enterprise Support plan"], answer: 2, explanation: "CloudTrail event history keeps management events for 90 days at no charge. To keep API activity longer, create a trail that delivers log files to an S3 bucket, or use CloudTrail Lake. VPC Flow Logs capture network traffic, not API calls, and CloudWatch monitoring captures performance metrics.", domain: "domain2", section: "clf-14" },
  { id: "clf-q-088", question: "A security team wants every S3 bucket in the account continuously checked, and flagged as noncompliant if it allows public read access. Which service provides this with a managed rule?", options: ["AWS CloudTrail","AWS Config","Amazon CloudWatch","Amazon Inspector"], answer: 1, explanation: "AWS Config continuously evaluates resource settings against rules and offers managed rules that flag S3 buckets allowing public read or write access. It can also notify you or trigger automatic remediation. CloudTrail records the API call that changed the bucket, but it does not judge compliance.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-089", question: "A company has 20 AWS accounts in AWS Organizations and wants employees to sign in once with their corporate credentials to reach any account they are assigned to. Which service should it use?", options: ["Amazon Cognito","AWS Directory Service","AWS Security Token Service","AWS IAM Identity Center"], answer: 3, explanation: "IAM Identity Center, the successor to AWS Single Sign-On, gives workforce users one sign-in to multiple AWS accounts and business applications, and it can connect to an existing identity provider such as Active Directory or Okta. Cognito is for customers of your own web and mobile apps, not employees.", domain: "domain2", section: "clf-19" },
  { id: "clf-q-090", question: "A company stores sensitive documents in Amazon S3. Under the Shared Responsibility Model, which task belongs to the company?", options: ["Replacing failed disks that store the objects","Patching the servers that run Amazon S3","Keeping the S3 service itself available","Setting bucket policies and encryption"], answer: 3, explanation: "For S3, AWS runs the storage hardware, the servers, and the availability of the service. The customer controls who can access the data through bucket policies and IAM, chooses encryption settings, and decides whether to enable features like versioning. Remember: AWS secures the service, you secure your data.", domain: "domain2", section: "clf-08" },
  { id: "clf-q-091", question: "A company wants to run a penetration test against its own Amazon EC2 instances and Amazon RDS databases to find weaknesses. What does AWS policy require?", options: ["Submitting a request and waiting for AWS approval","Nothing extra, since it may proceed without approval","Opening a support case to book a test window","Subscribing to AWS Shield Advanced beforehand"], answer: 1, explanation: "Customers may penetration test a list of services, including EC2, RDS, Aurora, CloudFront, Lambda and API Gateway, without prior approval. Asking for approval is tempting because AWS once required it, but that rule was dropped. Denial of service and flooding tests remain prohibited under this policy.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-092", question: "What is a key difference between IAM users and IAM roles?", options: ["Users have long-term credentials; roles give temporary ones","Users are meant for AWS services; roles are only for people","Users can be granted policies; roles cannot have policies","Users work in one Region; roles work in every Region"], answer: 0, explanation: "IAM users have long-term credentials like passwords and access keys. Roles have no permanent credentials: whoever assumes a role gets temporary credentials that expire. Roles are used by AWS services, federated users, and other accounts. Both users and roles are global, and both can have policies attached.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-093", question: "A developer accidentally pushed IAM access keys to a public code repository. What should be done FIRST?", options: ["Wait for AWS to rotate the exposed keys","Make the repository private and keep the keys","Deactivate the exposed keys and issue new ones","Change the IAM user's console password"], answer: 2, explanation: "Exposed keys must be deactivated immediately, then deleted and replaced, because attackers scan public repositories for keys. Then review CloudTrail for unauthorized activity. Making the repository private does not revoke copies already taken, and changing the console password does not affect access keys.", domain: "domain2", section: "clf-04" },
  { id: "clf-q-094", question: "A financial company's regulator requires encryption keys to be stored in dedicated, single-tenant hardware security modules that only the company controls. Which service meets this requirement?", options: ["AWS Key Management Service","AWS CloudHSM","AWS Secrets Manager","AWS Certificate Manager"], answer: 1, explanation: "CloudHSM provides dedicated, single-tenant hardware security modules in the AWS Cloud, and the customer alone manages the keys. KMS also protects keys in hardware security modules, but they are multi-tenant and managed by AWS, so KMS alone does not meet a dedicated hardware requirement.", domain: "domain2", section: "clf-16" },
  { id: "clf-q-095", question: "A company protects its application with IAM, security groups, network ACLs, AWS WAF, and encryption, so that if one control fails the others still protect it. Which security principle is this?", options: ["Least privilege access","Traceability","Defense in depth","Separation of duties"], answer: 2, explanation: "Defense in depth means stacking several layers of security controls, such as identity, network, application, and data protection, so a single failure does not expose the workload. The Well-Architected security pillar calls this applying security at all layers. Traceability means logging and monitoring actions instead.", domain: "domain2", section: "clf-21" },
  { id: "clf-q-096", question: "A company moves a scheduled job from EC2 to AWS Lambda. Under the Shared Responsibility Model, which task does the company STILL own?", options: ["Limiting the execution role to needed permissions","Patching the operating system that runs the code","Adding servers when many invocations arrive","Maintaining the physical hosts in the data center"], answer: 0, explanation: "With Lambda, AWS patches the operating system, scales the servers, and runs the data centers. The customer still owns its code, configuration, and access control, including keeping the execution role to least privilege. Patching is tempting because it was the company's job on EC2, but for Lambda it moves to AWS.", domain: "domain2", section: "clf-10" },
  { id: "clf-q-097", question: "A company's production database runs on Amazon RDS. It must keep working, with automatic failover, if the Availability Zone hosting the database has an outage. What should the company enable?", options: ["An RDS Multi-AZ deployment","An RDS read replica","Hourly manual snapshots","A larger instance class"], answer: 0, explanation: "Multi-AZ keeps a synchronized standby in another Availability Zone and fails over to it automatically, keeping the same endpoint. A read replica is tempting, but it exists to scale reads, and promoting it is a manual step. Snapshots restore data, not uptime.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-098", question: "Amazon S3 stores each file together with its metadata under a unique key, and applications reach it through an API over HTTPS. What type of storage is this?", options: ["Block storage","Object storage","Relational database storage","File storage"], answer: 1, explanation: "S3 is object storage: each object is data plus metadata, found by its key inside a bucket, with virtually unlimited capacity. Block storage, like EBS, acts as a disk attached to one instance. File storage, like EFS, is a shared file system with folders that many servers mount.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-099", question: "A company runs a distributed NoSQL database that needs very high, low-latency reads and writes to large datasets on local disks. Which EC2 instance family is the BEST fit?", options: ["Compute optimized, such as C instances","Memory optimized, such as R instances","Storage optimized, such as I instances","Accelerated computing, such as P instances"], answer: 2, explanation: "Storage optimized instances, like the I family, have fast local SSD storage built for heavy disk reads and writes, such as NoSQL databases, data warehouses, and distributed file systems. Memory optimized instances are tempting for databases, but they add RAM, not local disk throughput.", domain: "domain3", section: "clf-05" },
  { id: "clf-q-100", question: "A company wants to run a small piece of code each time an image is uploaded to an S3 bucket. It does not want to manage servers and wants to pay nothing while idle. Which service should it use?", options: ["Amazon EC2","Amazon Lightsail","Amazon ECS","AWS Lambda"], answer: 3, explanation: "AWS Lambda runs code in response to events, such as an S3 upload, with no servers to manage. You pay per request and per millisecond of run time, so idle time costs nothing. EC2 and Lightsail keep servers running and billing while idle, and ECS runs long-lived containers rather than short event-driven functions.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-101", question: "A news website serves the same images and videos to readers around the world, and pages load slowly for readers far from the origin Region. Which service caches this content at edge locations close to users?", options: ["Amazon CloudFront","AWS Global Accelerator","AWS Direct Connect","Amazon Route 53"], answer: 0, explanation: "CloudFront is the AWS content delivery network. It caches copies of content at hundreds of edge locations, so repeat requests are served near the user. Global Accelerator also uses the AWS edge network, but it caches nothing; it routes TCP and UDP traffic to your endpoints over the AWS backbone.", domain: "domain3", section: "clf-12" },
  { id: "clf-q-102", question: "A company wants a logically isolated network in AWS where it chooses its own IP address ranges, subnets, and route tables. What should it create?", options: ["An AWS Direct Connect link","An Amazon VPC","An AWS Organizations account","An AWS Outposts rack"], answer: 1, explanation: "A Virtual Private Cloud, or VPC, is your own private, isolated network inside an AWS Region. You define its IP range, split it into subnets across Availability Zones, and control routing. Direct Connect is only a private link from your data center into AWS, not the network itself.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-103", question: "A startup wants to register a new domain name and manage its DNS records on AWS so the name points to its web servers. Which service should it use?", options: ["Amazon CloudFront","AWS Direct Connect","Amazon Route 53","Amazon API Gateway"], answer: 2, explanation: "Route 53 is the AWS DNS service. It registers domain names and hosts the DNS records that translate names like example dot com into IP addresses or AWS resources. CloudFront can sit behind a domain name, but it is a content delivery network, not a DNS or domain registration service.", domain: "domain3", section: "clf-12" },
  { id: "clf-q-104", question: "A bank must keep old records for 10 years to meet regulations. The data is almost never read, and waiting up to 48 hours for a retrieval is acceptable. Which S3 storage class is MOST cost-effective?", options: ["S3 Glacier Deep Archive","S3 Standard-Infrequent Access","S3 Intelligent-Tiering","S3 Glacier Instant Retrieval"], answer: 0, explanation: "Glacier Deep Archive is the lowest-cost S3 storage class, built for long-term archives read maybe once or twice a year. Standard retrievals finish within 12 hours and bulk retrievals within 48 hours. Glacier Instant Retrieval returns data in milliseconds, a speed you pay more for and do not need here.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-105", question: "A development team wants a fully managed service that compiles its source code, runs unit tests, and produces packages ready to deploy. It wants to pay only for build minutes, with no build servers to manage. Which service should it use?", options: ["AWS CodePipeline","AWS CodeDeploy","AWS CodeArtifact","AWS CodeBuild"], answer: 3, explanation: "CodeBuild is a managed build service: it compiles code, runs tests, and produces artifacts, billed per build minute. CodePipeline is tempting, but it only orchestrates the stages of a release and hands the build step to a service like CodeBuild. CodeDeploy rolls out finished versions to servers.", domain: "domain3", section: "clf-11" },
  { id: "clf-q-106", question: "EC2 instances in a private subnet must read objects from Amazon S3. Security requires that this traffic never goes over the public internet. What is the MOST cost-effective solution?", options: ["NAT gateway","Internet gateway","AWS Direct Connect","VPC gateway endpoint"], answer: 3, explanation: "A gateway VPC endpoint gives private subnets a private route to S3 or DynamoDB over the AWS network, with no internet path and no extra charge. A NAT gateway is tempting, but it routes through an internet gateway to public endpoints and charges per gigabyte. Direct Connect links on-premises sites, not a VPC to S3.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-107", question: "A company wants to lift and shift 200 on-premises virtual machines to Amazon EC2 with minimal downtime and without rewriting the applications. Which service should it use?", options: ["AWS Database Migration Service","AWS Application Discovery Service","AWS Storage Gateway","AWS Application Migration Service"], answer: 3, explanation: "AWS Application Migration Service rehosts servers by continuously replicating their disks to AWS, then launching them as EC2 instances at cutover with minimal downtime. Application Discovery Service only collects inventory and dependency data to plan a migration; it moves nothing. Database Migration Service moves databases, not whole servers.", domain: "domain3", section: "clf-20" },
  { id: "clf-q-108", question: "An analyst wants to run standard SQL queries directly on CSV and Parquet log files stored in Amazon S3, with the LEAST setup and no database or servers to manage. Which service should the analyst use?", options: ["Amazon Redshift","Amazon RDS","Amazon DynamoDB","Amazon Athena"], answer: 3, explanation: "Athena is a serverless query service. You point it at data in S3, write standard SQL, and pay for the amount of data scanned. Redshift can also run SQL on large data, but it is a data warehouse you set up and usually load data into, which is more work for quick ad hoc queries.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-109", question: "An EBS volume is attached to an EC2 instance in one Availability Zone. The team needs a point-in-time backup that can be restored as a new volume in a different Availability Zone. What should it use?", options: ["An EBS snapshot","EBS Multi-Attach","An EC2 instance store volume","An S3 Lifecycle rule"], answer: 0, explanation: "An EBS volume is locked to one Availability Zone, but a snapshot is an incremental backup stored at the Region level. You can create a new volume from it in any Availability Zone, or copy it to another Region. Multi-Attach shares one volume with several instances in the same zone; it is not a backup.", domain: "domain3", section: "clf-06" },
  { id: "clf-q-110", question: "A company runs batch jobs for scientific modeling and video encoding that need high CPU performance but only modest memory. Which EC2 instance family is the BEST fit?", options: ["Compute optimized, such as C instances","Memory optimized, such as R instances","General purpose, such as T instances","Storage optimized, such as I instances"], answer: 0, explanation: "Compute optimized instances, the C family, have high-performance processors for CPU-bound work like batch processing, media encoding, scientific modeling, and dedicated game servers. General purpose instances balance CPU and memory, and burstable T instances suit light workloads with occasional spikes, not sustained heavy CPU.", domain: "domain3", section: "clf-05" },
  { id: "clf-q-111", question: "A company needs EC2 instances for an in-memory database that keeps very large datasets in RAM for fast queries. Which EC2 instance family is the BEST fit?", options: ["Memory optimized, such as R instances","Compute optimized, such as C instances","General purpose, such as T instances","Accelerated computing, such as P instances"], answer: 0, explanation: "Memory optimized instances, like the R family, provide a high ratio of RAM to CPU for workloads that process large datasets in memory, such as in-memory databases, caches, and real-time big data analytics. Compute optimized instances have more CPU per gigabyte of memory, so they suit CPU-bound work instead.", domain: "domain3", section: "clf-05" },
  { id: "clf-q-112", question: "A developer is deciding whether a nightly job can run on AWS Lambda. What is the maximum run time of a single Lambda invocation?", options: ["5 minutes","15 minutes","60 minutes","No limit, it runs until finished"], answer: 1, explanation: "A single Lambda invocation can run for at most 15 minutes. Work that takes longer should be split into smaller steps coordinated by Step Functions, or run on AWS Batch, ECS with Fargate, or EC2. Remember: Lambda is for short, event-driven tasks, not long-running processes.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-113", question: "A small business owner with little AWS experience wants to launch a WordPress site on a virtual server for a predictable, low monthly price. Which service is the SIMPLEST choice?", options: ["AWS Fargate","Amazon EC2","AWS Lambda","Amazon Lightsail"], answer: 3, explanation: "Lightsail bundles a virtual server, storage, and data transfer for a fixed monthly price, with ready-made blueprints like WordPress, and targets people with little cloud experience. EC2 can also host WordPress, but you configure the instance, storage, networking, and pricing yourself, which is more work than this owner needs.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-114", question: "A company already runs its containers with Kubernetes on premises and wants AWS to manage the Kubernetes control plane after moving to the cloud. Which service should it use?", options: ["Amazon ECS","AWS Fargate","Amazon ECR","Amazon EKS"], answer: 3, explanation: "Amazon EKS is managed Kubernetes. AWS runs the Kubernetes control plane, and teams keep using standard Kubernetes tools and manifests. ECS is the AWS-native container orchestrator, so Kubernetes workloads would need reworking. Fargate is a serverless way to run containers for ECS or EKS, not an orchestrator on its own.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-115", question: "A development team builds Docker images and needs a private, managed place on AWS to store and version them so that Amazon ECS can pull them. Which service should it use?", options: ["Amazon ECR","AWS CodeArtifact","AWS CodeBuild","Amazon EFS"], answer: 0, explanation: "Amazon Elastic Container Registry stores, versions, and scans container images, and ECS, EKS, and Fargate pull images from it. CodeArtifact is a repository for software packages such as npm or Maven libraries, not container images. CodeBuild can build the image, but it does not store it.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-116", question: "A team runs its web API as containers on Amazon ECS and wants to stop provisioning, patching, and scaling the EC2 instances in the cluster. What should it use?", options: ["Amazon EC2 Auto Scaling","Amazon ECR","AWS Fargate","AWS Batch"], answer: 2, explanation: "Fargate is serverless compute for containers. You set CPU and memory per task, and AWS runs it with no EC2 instances for you to manage. It works with both ECS and EKS. EC2 Auto Scaling would add and remove instances automatically, but the team would still patch and manage those servers.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-117", question: "A web application runs on several EC2 instances across two Availability Zones. The company wants one endpoint that spreads incoming requests across the healthy instances. Which service should it use?", options: ["Elastic Load Balancing","Amazon EC2 Auto Scaling","Amazon CloudFront","AWS Transit Gateway"], answer: 0, explanation: "Elastic Load Balancing gives one endpoint that distributes traffic across targets in multiple Availability Zones and stops sending requests to instances that fail health checks. Auto Scaling is often paired with it, but it changes how many instances run rather than distributing requests. Remember: the load balancer spreads traffic, Auto Scaling adjusts capacity.", domain: "domain3", section: "clf-07" },
  { id: "clf-q-118", question: "An application must send requests for the /api path to one group of EC2 instances and requests for the /images path to another group. Which type of load balancer supports this?", options: ["Network Load Balancer","Gateway Load Balancer","Application Load Balancer","Classic Load Balancer"], answer: 2, explanation: "The Application Load Balancer works at layer 7, HTTP and HTTPS, so it can route by URL path, host name, or headers. The Network Load Balancer works at layer 4 for TCP and UDP with ultra-low latency, but cannot read URL paths. The Classic Load Balancer is a legacy option without path-based routing.", domain: "domain3", section: "clf-07" },
  { id: "clf-q-119", question: "An online store's traffic doubles every evening and drops overnight. The company wants EC2 capacity to grow and shrink automatically to match demand. Which feature should it use?", options: ["Elastic Load Balancing","Amazon EC2 Auto Scaling","Amazon CloudWatch","AWS Lambda"], answer: 1, explanation: "An EC2 Auto Scaling group adds instances when demand rises and removes them when it falls, using rules like a target CPU level or a schedule, and it replaces unhealthy instances. This is elasticity. CloudWatch supplies the metrics and alarms that can trigger scaling, but it does not launch or terminate instances itself.", domain: "domain3", section: "clf-07" },
  { id: "clf-q-120", question: "A marketing team needs to host a static website made only of HTML, CSS, JavaScript, and image files. It wants the lowest cost and no servers to manage. Which service should it use?", options: ["Amazon S3","Amazon EC2","Amazon EFS","Amazon Lightsail"], answer: 0, explanation: "S3 can host a static website straight from a bucket, with no servers and pay-per-use pricing, and CloudFront can be added in front for speed and HTTPS. EC2 and Lightsail would work, but they mean running and patching a web server. EFS is a file system for instances, not a website host.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-121", question: "A research lab wants to store very large single files, such as 8 TB genome datasets, as individual objects in Amazon S3. What is the maximum size of one S3 object today?", options: ["5 GB","5 TB","50 TB","There is no limit"], answer: 2, explanation: "Since December 2025, one S3 object can be up to 50 terabytes, ten times the old 5 terabyte limit that many courses still mention. A single PUT upload is capped at 5 gigabytes, so large files use multipart upload. Total bucket storage is unlimited, but each object has a maximum size.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-122", question: "A company stores data in S3 but cannot predict how often each object will be accessed, and the patterns change over time. It wants objects moved to cheaper tiers automatically, with no retrieval fees. Which option fits BEST?", options: ["S3 Intelligent-Tiering","S3 Versioning","S3 Lifecycle rules","S3 Replication"], answer: 0, explanation: "S3 Intelligent-Tiering watches each object's access and moves it between access tiers automatically, for a small monitoring fee and no retrieval fees. Lifecycle rules also move objects, but on a fixed, age-based schedule you define, so they suit known access patterns, not unknown or changing ones.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-123", question: "Employees sometimes overwrite or delete important files in an S3 bucket by mistake. The company wants to be able to recover the earlier copies. Which S3 feature should it enable?", options: ["S3 Transfer Acceleration","S3 Replication","S3 Versioning","S3 Intelligent-Tiering"], answer: 2, explanation: "S3 Versioning keeps every version of an object in the same bucket. An overwrite creates a new version, and a delete only adds a delete marker, so older versions can be restored. Replication copies objects to another bucket, but it is not an undo feature, and it requires versioning to be turned on first.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-124", question: "A manager asks how likely it is that data stored in S3 Standard will be lost. What durability is S3 Standard designed for?", options: ["Three nines, 99.9%","Four nines, 99.99%","Five nines, 99.999%","Eleven nines, 99.999999999%"], answer: 3, explanation: "S3 Standard is designed for eleven nines of durability, because objects are stored redundantly across at least three Availability Zones. Four nines is the tempting trap: that is the designed availability of S3 Standard, meaning how often you can reach the data, not how safe it is from loss.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-125", question: "An application needs the highest possible disk speed for temporary scratch data and caches, and it is fine if the data disappears when the instance stops. Which EC2 storage option is the BEST fit?", options: ["An Amazon EBS gp3 volume","EC2 instance store","Amazon EFS","Amazon S3"], answer: 1, explanation: "Instance store is physical disk on the host server, giving very high input and output performance at no extra cost. It is ephemeral: data is lost if the instance stops, hibernates, or terminates, so it suits caches, buffers, and scratch data. EBS volumes persist independently of the instance, but they are network-attached.", domain: "domain3", section: "clf-06" },
  { id: "clf-q-126", question: "Ten Linux EC2 instances spread across several Availability Zones must read and write the same files at the same time. Which storage service should they use?", options: ["Amazon S3","Amazon EFS","Amazon EBS","EC2 instance store"], answer: 1, explanation: "Amazon EFS is a managed NFS file system that many Linux instances can mount at once, across Availability Zones, and it grows automatically. An EBS volume normally attaches to one instance in one zone, and Multi-Attach is limited to a few instances in the same zone. S3 is object storage, not a shared file system.", domain: "domain3", section: "clf-06" },
  { id: "clf-q-127", question: "A company wants a cloud-native relational database that is compatible with MySQL and PostgreSQL, performs better than the standard engines, and grows its storage automatically. Which service should it choose?", options: ["Amazon DynamoDB","Amazon Aurora","Amazon Redshift","Amazon Neptune"], answer: 1, explanation: "Aurora is the AWS-built relational engine, compatible with MySQL and PostgreSQL. AWS cites up to five times the throughput of standard MySQL and three times that of PostgreSQL, and storage grows automatically with six copies across three Availability Zones. DynamoDB is NoSQL, and Redshift is an analytics data warehouse.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-128", question: "A mobile game needs a serverless key-value database that responds in single-digit milliseconds whether it has 100 players or 100 million. Which service fits BEST?", options: ["Amazon RDS","Amazon Redshift","Amazon DynamoDB","Amazon Neptune"], answer: 2, explanation: "DynamoDB is a fully managed, serverless NoSQL key-value and document database built for consistent single-digit millisecond performance at any scale. RDS is relational and scales mainly by resizing instances and adding read replicas, so it is not the best fit for massive, unpredictable key-value traffic.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-129", question: "A retailer wants to run complex analytical SQL queries across several years of sales data, many terabytes in size, to build business reports. Which service is designed for this?", options: ["Amazon RDS for MySQL","Amazon Redshift","Amazon ElastiCache","Amazon DynamoDB"], answer: 1, explanation: "Redshift is a data warehouse built for analytics. It stores data in columns and runs complex SQL queries across terabytes to petabytes. RDS is built for day-to-day transactional workloads and slows down on huge analytical scans. Remember: analytics or data warehouse points to Redshift.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-130", question: "A social media startup needs to store users, their friends, and friends of friends, and quickly suggest people a user might know. Which database fits BEST?", options: ["Amazon Neptune","Amazon RDS","Amazon DynamoDB","Amazon Redshift"], answer: 0, explanation: "Neptune is a managed graph database for highly connected data, such as social networks, recommendation engines, and fraud detection, where relationships matter as much as the records. Relational or key-value databases can store relationships, but querying many levels of connections is slow and complex. Remember: relationships and connections point to Neptune.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-131", question: "An application's Amazon RDS database is overloaded by the same read queries repeated thousands of times per minute. Which service can cache the results in memory to cut latency and database load?", options: ["Amazon CloudFront","Amazon DynamoDB","Amazon EBS","Amazon ElastiCache"], answer: 3, explanation: "ElastiCache is a managed in-memory cache running Valkey, Redis OSS, or Memcached. The app stores frequent query results there and reads them back in microseconds, taking load off the database. CloudFront caches web content at edge locations for end users, not database query results inside your application.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-132", question: "A company wants to migrate its on-premises Oracle database to Amazon Aurora PostgreSQL while the source database stays online during the move. Which service should it use?", options: ["AWS DataSync","AWS Application Migration Service","AWS Database Migration Service","AWS Backup"], answer: 2, explanation: "AWS Database Migration Service moves data into AWS databases while the source keeps running, and can replicate ongoing changes until cutover. For a different engine, like Oracle to PostgreSQL, the Schema Conversion Tool or DMS Schema Conversion converts the schema first. Application Migration Service rehosts whole servers and does not convert database engines.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-133", question: "An EC2 web server in a public subnet must be reachable from the internet. Which component must be attached to the VPC and added to the subnet's route table?", options: ["NAT gateway","Internet gateway","Virtual private gateway","VPC peering connection"], answer: 1, explanation: "An internet gateway attaches to a VPC and lets resources with public IP addresses send and receive internet traffic. A subnet is public because its route table sends internet-bound traffic to that gateway. A NAT gateway only lets private resources connect out; the internet cannot start connections to them.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-134", question: "EC2 instances in a private subnet need to download software updates from the internet, but must not accept connections started from the internet. What should be added?", options: ["An internet gateway route in the private subnet","A security group allowing all inbound traffic","A NAT gateway in a public subnet","A virtual private gateway on the VPC"], answer: 2, explanation: "A NAT gateway sits in a public subnet and lets instances in private subnets start outbound connections to the internet, while connections started from outside are not allowed in. Routing the private subnet straight to an internet gateway would turn it into a public subnet, which breaks the requirement.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-135", question: "A company moves large amounts of data between its data center and AWS every day and needs consistent performance over a private, dedicated connection that avoids the public internet. Which service should it use?", options: ["AWS Direct Connect","Amazon CloudFront","AWS Site-to-Site VPN","AWS Global Accelerator"], answer: 0, explanation: "Direct Connect is a dedicated private network link from your premises to AWS, giving consistent bandwidth and latency without using the public internet, though it can take weeks to set up. Site-to-Site VPN is quicker and encrypted, but it runs over the public internet, so performance can vary.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-136", question: "A team is building a serverless back end with AWS Lambda and needs a managed front door to create, publish, secure, and throttle REST APIs for its mobile app. Which service should it use?", options: ["Amazon Route 53","AWS Step Functions","Amazon CloudFront","Amazon API Gateway"], answer: 3, explanation: "API Gateway is a fully managed service to create, publish, secure, and monitor REST, HTTP, and WebSocket APIs. It adds throttling, API keys, and authorization, and invokes Lambda or other back ends. Step Functions coordinates workflows between services, but it is not a public API front door for clients.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-137", question: "A company runs its application in two AWS Regions. It wants DNS to answer each user with the Region that gives that user the lowest latency. Which service provides this?", options: ["Amazon Route 53","AWS Global Accelerator","Amazon CloudFront","Elastic Load Balancing"], answer: 0, explanation: "Route 53 offers routing policies such as latency-based, geolocation, weighted, and failover, and can use health checks to skip unhealthy endpoints. Global Accelerator also sends users to a nearby healthy Region, but it does this with static anycast IP addresses on the AWS network, not with DNS answers.", domain: "domain3", section: "clf-12" },
  { id: "clf-q-138", question: "An operations team wants to be notified when the CPU utilization of an EC2 instance stays above 80 percent for 10 minutes. Which service should it use?", options: ["AWS CloudTrail","Amazon CloudWatch","AWS Config","AWS Trusted Advisor"], answer: 1, explanation: "CloudWatch collects metrics such as CPU utilization, and a CloudWatch alarm watches a metric and can notify through Amazon SNS or trigger Auto Scaling when a threshold is crossed. CloudTrail records who made which API calls, and Config tracks configuration changes; neither watches performance metrics.", domain: "domain3", section: "clf-14" },
  { id: "clf-q-139", question: "A new engineer keeps mixing up Amazon CloudWatch and AWS CloudTrail. Which statement correctly describes them?", options: ["Both services record every API call made in the account","CloudWatch records API calls; CloudTrail tracks configuration history","CloudWatch monitors metrics and logs; CloudTrail records API activity","CloudTrail monitors metrics and logs; CloudWatch records API activity"], answer: 2, explanation: "CloudWatch is for performance and operations: metrics, logs, alarms, and dashboards. CloudTrail is the audit trail: it records API calls, including who made them, when, and from where. Configuration history is AWS Config. Memory trick: CloudTrail leaves a trail of who did what, and CloudWatch watches how things are running.", domain: "domain3", section: "clf-14" },
  { id: "clf-q-140", question: "A microservices application is slow, and developers need to trace each request as it passes through API Gateway, Lambda, and DynamoDB to find the bottleneck. Which service should they use?", options: ["AWS X-Ray","AWS CloudTrail","AWS Config","Amazon Inspector"], answer: 0, explanation: "AWS X-Ray traces requests end to end across distributed applications and draws a service map showing where time is spent and where errors happen. CloudTrail records API calls for auditing, not application performance. Remember: tracing, debugging, and finding bottlenecks in microservices point to X-Ray.", domain: "domain3", section: "clf-14" },
  { id: "clf-q-141", question: "A retail company wants to set up a cloud-based customer contact center that handles phone calls and chats, without buying any telephony hardware. Which service should it use?", options: ["Amazon Lex","Amazon SNS","Amazon Polly","Amazon Connect"], answer: 3, explanation: "Amazon Connect is a cloud contact center: you set up phone numbers, call flows, and agent workspaces in minutes and pay per use. Lex is tempting because it builds chatbots and voice bots, and it often plugs into Connect, but Lex on its own is not a contact center.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-142", question: "A company must patch operating systems and run commands on hundreds of EC2 instances and on-premises servers from one place, without opening SSH ports. Which service should it use?", options: ["AWS Config","Amazon Inspector","AWS Systems Manager","AWS CloudFormation"], answer: 2, explanation: "Systems Manager manages fleets of EC2 and on-premises servers. Patch Manager automates patching, Run Command runs scripts at scale, and Session Manager gives secure shell access without open SSH ports or keys. Inspector finds missing patches and vulnerabilities, but it does not install the fixes.", domain: "domain3", section: "clf-11" },
  { id: "clf-q-143", question: "A photo-sharing app wants to automatically detect objects, scenes, faces, and inappropriate content in uploaded images and videos. Which service should it use?", options: ["Amazon Rekognition","Amazon Polly","Amazon Textract","Amazon Comprehend"], answer: 0, explanation: "Amazon Rekognition is the computer vision service for images and video. It finds objects, scenes, faces, celebrities, text in photos, and unsafe content. Textract also reads images, but it is built to pull text, forms, and tables out of documents, not to understand what a photo shows.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-144", question: "A company wants to build a chatbot that understands typed and spoken customer questions and can book appointments through a conversation. Which service should it use?", options: ["Amazon Polly","Amazon Rekognition","Amazon Comprehend","Amazon Lex"], answer: 3, explanation: "Amazon Lex builds conversational interfaces, both chatbots and voice bots, using speech recognition and language understanding, the same technology behind Alexa. Comprehend analyzes text for sentiment and key phrases, but it does not hold a conversation. Polly only speaks text aloud.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-145", question: "An e-learning company wants to turn its written lessons into natural-sounding audio narration in several languages. Which service should it use?", options: ["Amazon Transcribe","Amazon Polly","Amazon Comprehend","Amazon Lex"], answer: 1, explanation: "Amazon Polly converts text into lifelike speech in many languages and voices. Transcribe does the opposite, turning speech into text, which makes it the classic trap. Memory trick: Polly is a parrot, so it talks. Transcribe writes down what it hears.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-146", question: "A company records its customer support calls and wants to automatically convert the recordings into searchable text. Which service should it use?", options: ["Amazon Polly","Amazon Comprehend","Amazon Translate","Amazon Transcribe"], answer: 3, explanation: "Amazon Transcribe is automatic speech recognition: it converts speech in audio and video into text, useful for call transcripts, captions, and subtitles. Polly goes the other way, from text to speech. Comprehend could then analyze the transcript, but it cannot listen to audio.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-147", question: "An online store wants to analyze thousands of written product reviews to learn whether customers feel positive or negative and which products they mention. Which service should it use?", options: ["Amazon Rekognition","Amazon Comprehend","Amazon Lex","Amazon Kendra"], answer: 1, explanation: "Amazon Comprehend uses natural language processing to find sentiment, entities, key phrases, language, and topics in text. Kendra also works with text, but it is an enterprise search service that answers questions from documents rather than analyzing sentiment. Rekognition analyzes images and video, not written reviews.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-148", question: "A team of data scientists wants to build, train, and deploy its own custom machine learning models on fully managed infrastructure. Which service should it use?", options: ["Amazon Lex","Amazon Comprehend","Amazon Rekognition","Amazon SageMaker AI"], answer: 3, explanation: "Amazon SageMaker AI, formerly just SageMaker, is the managed platform for the whole machine learning workflow: preparing data, building, training, tuning, and deploying custom models. Lex, Comprehend, and Rekognition are pre-trained AI services you call through an API when you do not want to build your own model.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-149", question: "An insurance company receives thousands of scanned claim forms and wants to automatically extract the printed text, handwriting, and table data from them. Which service should it use?", options: ["Amazon Textract","Amazon Rekognition","Amazon Macie","Amazon Comprehend"], answer: 0, explanation: "Amazon Textract extracts text, handwriting, forms, and tables from scanned documents and PDFs, keeping structure such as field names and values. Rekognition can spot text in photos, like street signs, but it is not built to read forms. Macie finds sensitive data in S3, and Comprehend analyzes text that is already extracted.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-150", question: "A company wants one central place to set backup schedules and retention for its EBS volumes, RDS databases, DynamoDB tables, and EFS file systems, including copies to another Region. Which service should it use?", options: ["AWS Storage Gateway","AWS Elastic Disaster Recovery","AWS Backup","AWS Config"], answer: 2, explanation: "AWS Backup centrally manages and automates backups across many AWS services using backup plans, with schedules, retention rules, and cross-Region or cross-account copies. Elastic Disaster Recovery continuously replicates servers so they can be recovered quickly after an outage; it is not a policy-based backup tool for databases and file systems.", domain: "domain3", section: "clf-20" },
  { id: "clf-q-151", question: "A company needs to give 300 remote employees secure, managed Windows desktops that they can use from their own laptops, without shipping any hardware. Which service should it use?", options: ["Amazon WorkSpaces","Amazon WorkSpaces Applications","Amazon Lightsail","AWS Outposts"], answer: 0, explanation: "Amazon WorkSpaces provides managed virtual desktops, Windows or Linux, that users reach from almost any device, known as desktop as a service. WorkSpaces Applications, formerly AppStream 2.0, is the tempting choice, but it streams individual applications rather than giving each user a full desktop.", domain: "domain3", section: "clf-20" },
  { id: "clf-q-152", question: "A developer wants a Python application to upload files to Amazon S3 by calling AWS APIs directly from its own code. What should the developer use?", options: ["The AWS Management Console","The AWS CLI","An AWS SDK","AWS CloudFormation"], answer: 2, explanation: "AWS SDKs are libraries for programming languages, such as Boto3 for Python, that let an application call AWS APIs from its own code. The CLI is for typing or scripting commands in a terminal, and the Management Console is the web interface for people. All three use the same underlying AWS APIs.", domain: "domain3", section: "clf-04" },
  { id: "clf-q-153", question: "A developer wants to upload a Java web application and have AWS handle capacity provisioning, load balancing, auto scaling, and health monitoring, while keeping access to the underlying EC2 instances. Which service fits BEST?", options: ["Amazon ECS","AWS Elastic Beanstalk","AWS CloudFormation","Amazon Lightsail"], answer: 1, explanation: "Elastic Beanstalk is a platform as a service: you upload code, and it deploys and manages the load balancer, Auto Scaling group, and EC2 instances for you, with no charge beyond those resources. CloudFormation can build the same resources, but you must define every one of them yourself in templates.", domain: "domain3", section: "clf-11" },
  { id: "clf-q-154", question: "A company wants to load streaming application log data into Amazon S3 and Amazon Redshift in near real time, with no consumer code to write and no capacity to manage. Which service should it use?", options: ["Amazon SQS","Amazon Kinesis Data Streams","Amazon SNS","Amazon Data Firehose"], answer: 3, explanation: "Amazon Data Firehose, formerly Kinesis Data Firehose, is fully managed: it batches incoming streaming data and delivers it to destinations such as S3, Redshift, and OpenSearch, scaling automatically. Kinesis Data Streams is tempting, but you must write consumer applications to read and deliver the data.", domain: "domain3", section: "clf-13" },
  { id: "clf-q-155", question: "When a new order is placed, a company wants one message delivered at the same time to an email address, a Lambda function, and two SQS queues. Which service should it use?", options: ["Amazon SNS","Amazon SQS","Amazon SES","Amazon Kinesis Data Streams"], answer: 0, explanation: "Amazon SNS is publish and subscribe messaging. A message published to one topic is pushed to every subscriber at once, including email, SMS, Lambda functions, SQS queues, and HTTP endpoints. This is called fan-out. SQS is a queue that workers pull from, so on its own it does not push to many destinations.", domain: "domain3", section: "clf-13" },
  { id: "clf-q-156", question: "A company wants to send order confirmations and monthly marketing newsletters by email to millions of customers from its own domain. Which service is designed for this?", options: ["Amazon SNS","Amazon SES","Amazon Connect","Amazon SQS"], answer: 1, explanation: "Amazon Simple Email Service, or SES, is built for sending transactional and marketing email at scale, with your own domain, templates, and delivery tracking. SNS can send simple email notifications to people who subscribe to a topic, but it is not meant for branded newsletters or bulk customer email.", domain: "domain3", section: "clf-20" },
  { id: "clf-q-157", question: "A company wants to collect website clickstream data and IoT sensor readings and process them in real time as they arrive. Which service should it use?", options: ["Amazon SQS standard queues","AWS Batch job queues","Amazon Kinesis Data Streams","Amazon Redshift Serverless"], answer: 2, explanation: "Amazon Kinesis collects and processes streaming data in real time, such as clickstreams, logs, and IoT telemetry, and lets several applications read the same stream. AWS Batch runs jobs on data that has already been gathered, not on a live stream. Remember: real-time streaming data points to Kinesis.", domain: "domain3", section: "clf-13" },
  { id: "clf-q-158", question: "A data team needs a serverless service that crawls data in Amazon S3 to discover its schema, stores that metadata in a central catalog, and runs extract, transform, and load jobs. Which service should it use?", options: ["Amazon Athena","Amazon Quick Sight","AWS Glue","Amazon Kinesis Data Streams"], answer: 2, explanation: "AWS Glue is a serverless data integration service. Crawlers discover the schema of your data, the Glue Data Catalog stores that metadata, and Glue jobs extract, transform, and load it. Athena is tempting because it queries S3 with SQL, but it does not crawl or transform data; it reads table definitions from the Glue Data Catalog.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-159", question: "A company wants its on-premises applications to keep using local file shares, while the data is actually stored in Amazon S3 and recently used files are cached locally for fast access. Which service should it use?", options: ["AWS Storage Gateway","AWS Direct Connect","AWS DataSync","Amazon EFS"], answer: 0, explanation: "AWS Storage Gateway is hybrid cloud storage. It gives on-premises applications local file, volume, or tape interfaces while storing the data in AWS, and caches frequently used data on site. DataSync copies data into AWS as a transfer job, but it does not give on-premises apps an ongoing local share backed by the cloud.", domain: "domain3", section: "clf-08" },
  { id: "clf-q-160", question: "A company wants to trigger a Lambda function every night at 2 AM, and also whenever an EC2 instance changes to the stopped state. Which service should it use?", options: ["AWS Step Functions","Amazon SQS","AWS Config","Amazon EventBridge"], answer: 3, explanation: "Amazon EventBridge, formerly CloudWatch Events, is a serverless event bus. Rules match events from AWS services, SaaS apps, or your own apps, or run on a schedule, and send them to targets like Lambda. Step Functions coordinates the steps inside a workflow, but it does not watch for events or run schedules by itself.", domain: "domain3", section: "clf-14" },
  { id: "clf-q-161", question: "A company wants to run an order process in which several Lambda functions execute in a set order, with retries, error handling, and a wait for human approval. Which service should it use?", options: ["Amazon EventBridge","AWS Step Functions","Amazon SQS","AWS CloudFormation"], answer: 1, explanation: "AWS Step Functions builds visual workflows, called state machines, that coordinate Lambda functions and other services in order, with built-in retries, branching, error handling, and waits for approval. EventBridge routes individual events to targets, but it does not track the state of a long, multi-step process.", domain: "domain3", section: "clf-20" },
  { id: "clf-q-162", question: "A factory needs to run AWS services on premises for very low latency to local machines and to keep data on site, using the same AWS APIs and tools. Which service should it use?", options: ["AWS Local Zones","AWS Outposts","AWS Wavelength","AWS Direct Connect"], answer: 1, explanation: "AWS Outposts delivers AWS-managed racks and servers into your own data center, so you run EC2, EBS, and other services on site with the same APIs and console. Local Zones place AWS infrastructure near large cities, but in AWS facilities, not inside your building. Wavelength sits inside telecom 5G networks.", domain: "domain3", section: "clf-12" },
  { id: "clf-q-163", question: "A team wants every code change pushed to its repository to be automatically built, tested, and deployed through a series of stages. Which service orchestrates this release process?", options: ["AWS CodeBuild","AWS CloudFormation","AWS CodePipeline","AWS Systems Manager"], answer: 2, explanation: "AWS CodePipeline is a continuous delivery service that orchestrates release stages, such as source, build, test, and deploy, every time code changes. CodeBuild is the tempting answer, but it only compiles code and runs tests as one step inside the pipeline. Remember: pipeline means the whole automated flow.", domain: "domain3", section: "clf-11" },
  { id: "clf-q-164", question: "A company has two VPCs, one for its application and one for shared tools, and wants instances in each to talk to each other using private IP addresses. What is the SIMPLEST solution?", options: ["An internet gateway in each VPC","A VPC peering connection","A NAT gateway in each VPC","An AWS Direct Connect link"], answer: 1, explanation: "VPC peering privately connects two VPCs, even across accounts or Regions, so instances talk using private IP addresses over the AWS network. Peering is not transitive, so linking many VPCs needs many connections, which is where Transit Gateway helps. Internet and NAT gateways send traffic toward the internet, not between private networks.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-165", question: "A company has 60 VPCs and several on-premises data centers, and wants to connect all of them through one central hub instead of managing many separate connections. Which service should it use?", options: ["VPC peering","AWS PrivateLink","AWS Transit Gateway","NAT gateway"], answer: 2, explanation: "AWS Transit Gateway is a regional hub that connects thousands of VPCs and on-premises networks, through VPN or Direct Connect, in a hub-and-spoke design. VPC peering is not transitive, so 60 VPCs would need a huge mesh of connections. PrivateLink exposes a single service privately rather than joining whole networks.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-166", question: "A company needs to process petabytes of log data using open-source big data frameworks such as Apache Spark and Hadoop, without building the clusters by hand. Which service should it use?", options: ["Amazon RDS","Amazon DynamoDB","Amazon Redshift","Amazon EMR"], answer: 3, explanation: "Amazon EMR runs managed big data clusters with open-source frameworks such as Apache Spark, Hadoop, and Hive, and handles provisioning and scaling of the cluster. Redshift is tempting for large-scale analytics, but it is a SQL data warehouse, not a platform for running Spark or Hadoop jobs.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-167", question: "A research team needs to run thousands of containerized jobs that each take several hours. It wants AWS to queue the jobs and provision the right amount of compute automatically. Which service fits BEST?", options: ["AWS Batch","AWS Lambda","Amazon Lightsail","Amazon Kinesis Data Streams"], answer: 0, explanation: "AWS Batch queues and schedules batch jobs packaged as containers, and provisions EC2, Spot, or Fargate capacity sized to the work, so you pay only for the resources used. Lambda is tempting because it is serverless, but one invocation is limited to 15 minutes, so multi-hour jobs do not fit.", domain: "domain3", section: "clf-10" },
  { id: "clf-q-168", question: "Business managers want interactive dashboards and charts built from data in Amazon Redshift and Amazon S3, without managing any BI servers. Which service should they use?", options: ["AWS Glue","Amazon Athena","Amazon SageMaker AI","Amazon Quick Sight"], answer: 3, explanation: "Amazon Quick Sight, formerly QuickSight and now part of Amazon Quick, is the serverless business intelligence service for interactive dashboards, charts, and reports. Athena is tempting because it queries S3 data with SQL, but it returns query results, not shareable visual dashboards. Remember: dashboards and visualization point to Quick Sight.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-169", question: "Employees waste time hunting through thousands of internal documents, wikis, and manuals. The company wants them to ask questions in plain language and get precise answers from that content. Which service fits BEST?", options: ["Amazon Textract","Amazon Kendra","Amazon Athena","Amazon Comprehend"], answer: 1, explanation: "Amazon Kendra is an intelligent enterprise search service that uses machine learning to find answers inside documents from many sources, such as SharePoint, S3, and wikis. Comprehend analyzes text for sentiment and entities but does not search it. Textract pulls text from scans, and Athena runs SQL queries on data.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-170", question: "A company needs to connect its on-premises network to a VPC within a day, with encrypted traffic, at low cost. Sending the traffic over the public internet is acceptable. Which option should it choose?", options: ["AWS Direct Connect","AWS Site-to-Site VPN","AWS Client VPN","VPC peering"], answer: 1, explanation: "AWS Site-to-Site VPN creates encrypted IPsec tunnels between your on-premises network and a VPC over the public internet, and can be ready in minutes to hours. Direct Connect avoids the internet but takes weeks to provision. Client VPN connects individual users' devices, not a whole office network.", domain: "domain3", section: "clf-15" },
  { id: "clf-q-171", question: "A company is moving Windows-based applications that rely on SMB file shares and Microsoft Active Directory permissions to AWS. Which fully managed storage service fits BEST?", options: ["Amazon EFS One Zone file system","Amazon FSx for Lustre","Amazon FSx for Windows File Server","Amazon EBS Multi-Attach volumes"], answer: 2, explanation: "Amazon FSx for Windows File Server is a fully managed native Windows file system that uses the SMB protocol and integrates with Microsoft Active Directory. FSx for Lustre is built for high-performance Linux computing, and EFS is an NFS file system for Linux. Remember: Windows file shares point to FSx for Windows.", domain: "domain3", section: "clf-06" },
  { id: "clf-q-172", question: "A multiplayer game uses UDP and serves players worldwide. The company wants two static IP addresses, player traffic entering the AWS network at the nearest edge location, and fast failover between Regions. Which service fits BEST?", options: ["Amazon CloudFront","AWS Global Accelerator","Amazon Route 53","S3 Transfer Acceleration"], answer: 1, explanation: "AWS Global Accelerator gives you static anycast IP addresses and carries TCP and UDP traffic onto the AWS global network at the nearest edge location, then to the best healthy endpoint, with fast failover. CloudFront also uses edge locations, but it caches HTTP content and does not provide fixed IP addresses for UDP game traffic.", domain: "domain3", section: "clf-12" },
  { id: "clf-q-173", question: "A company must install a custom operating system configuration and specialized drivers, and needs full administrator control over the server. Which compute service should it use?", options: ["AWS Lambda","AWS Fargate","AWS Elastic Beanstalk","Amazon EC2"], answer: 3, explanation: "Amazon EC2 is infrastructure as a service. You choose the operating system, instance type, storage, and networking, and you have full root or administrator access. Elastic Beanstalk runs on EC2 but manages the platform for you, while Lambda and Fargate hide the operating system completely. More control also means more patching work.", domain: "domain3", section: "clf-05" },
  { id: "clf-q-174", question: "A company runs a MongoDB application on premises and wants a fully managed AWS database that is MongoDB compatible, with the LEAST changes to its code. Which service should it choose?", options: ["Amazon Neptune","Amazon DynamoDB","Amazon DocumentDB","Amazon Keyspaces"], answer: 2, explanation: "Amazon DocumentDB is a managed document database that is compatible with MongoDB APIs, so existing MongoDB code and tools keep working. DynamoDB also stores JSON-like items, but it has its own API, so the application would need rewriting. Keyspaces is for Apache Cassandra, and Neptune is a graph database.", domain: "domain3", section: "clf-09" },
  { id: "clf-q-175", question: "An online store wants to automatically translate its product descriptions and customer reviews into Spanish, French, and Japanese. Which service should it use?", options: ["Amazon Comprehend","Amazon Transcribe","Amazon Translate","Amazon Polly"], answer: 2, explanation: "Amazon Translate is neural machine translation that converts text from one language to another quickly and at scale. Comprehend can detect which language a text is written in, but it does not translate it. Transcribe turns speech into text, and Polly turns text into speech.", domain: "domain3", section: "clf-17" },
  { id: "clf-q-176", question: "A company is designing a new three-tier application and wants to estimate its monthly AWS bill BEFORE deploying any resources. Which AWS tool should it use?", options: ["AWS Cost Explorer","AWS Trusted Advisor","AWS Budgets","AWS Pricing Calculator"], answer: 3, explanation: "AWS Pricing Calculator lets you model services you have not built yet and produces a cost estimate you can share. Cost Explorer is tempting, but it only analyzes and forecasts spending from resources that already exist in your account.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-177", question: "A startup wants an email alert when its actual or forecasted monthly AWS costs go above a limit it sets. Which service should it use?", options: ["AWS Cost Explorer","AWS Pricing Calculator","AWS Budgets","AWS Trusted Advisor"], answer: 2, explanation: "AWS Budgets tracks actual and forecasted costs or usage against a threshold you set and sends alerts by email or Amazon SNS. Cost Explorer shows spending trends and forecasts, but it does not send threshold alerts on its own.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-178", question: "A large enterprise wants a designated Technical Account Manager (TAM) who knows its workloads and provides proactive guidance. Which AWS Support plan should it choose?", options: ["Basic Support","Enterprise Support","Business Support+","Developer Support"], answer: 1, explanation: "Enterprise Support includes a designated Technical Account Manager for proactive architecture and operations guidance. Business Support+ gives around-the-clock access to AWS experts but no TAM. Basic and Developer Support never include a TAM.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-179", question: "A company has 12 AWS accounts in AWS Organizations with consolidated billing. How does consolidated billing help the company lower its costs?", options: ["Combined usage reaches volume pricing tiers sooner","Data transfer between member accounts becomes free","Every member account gets Business Support+ free","Idle On-Demand instances switch to Spot pricing"], answer: 0, explanation: "Consolidated billing treats all accounts as one for pricing, so combined usage reaches volume discount tiers faster, and Reserved Instance and Savings Plans discounts can be shared across accounts. It does not make cross-account data transfer free, and it includes no support plan upgrade.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-180", question: "A company will run a steady web server workload 24 hours a day for the next 3 years and cannot tolerate interruptions. Which EC2 pricing option is MOST cost-effective?", options: ["On-Demand Instances","Spot Instances","3-year Reserved Instances","On-Demand Capacity Reservations"], answer: 2, explanation: "For a steady, always-on workload, 3-year Reserved Instances, like Savings Plans, save up to 72 percent compared with On-Demand. Spot is cheaper but can be interrupted with a two-minute warning. On-Demand Capacity Reservations guarantee capacity but are billed at full On-Demand rates.", domain: "domain4", section: "clf-05" },
  { id: "clf-q-181", question: "A company wants automated checks of its AWS account that flag idle resources, security groups open to the world, and services close to their quotas. Which service should it use?", options: ["Amazon CloudWatch","AWS Config","AWS Well-Architected Tool","AWS Trusted Advisor"], answer: 3, explanation: "Trusted Advisor inspects your account against best practices in six categories: cost optimization, performance, security, fault tolerance, service limits, and operational excellence. AWS Config evaluates resource configurations against rules, but it does not find idle resources or track service quotas.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-182", question: "A student creates a new AWS account in 2026 to learn AWS. Which statement about the AWS Free Tier for this new account is correct?", options: ["It offers sign-up credits plus always-free monthly allowances","It gives 12 months of free usage for EC2, S3, and RDS","It provides unlimited free usage of every service for a year","It includes free Business Support+ for the first six months"], answer: 0, explanation: "Since July 2025, new accounts get 100 US dollars in credits, can earn 100 more by completing activities, and keep over 30 always-free monthly allowances. The old 12-month free offers for services like EC2 and S3 no longer apply to new accounts.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-183", question: "A company copies 50 TB of files from its data center into Amazon S3 over the internet. How is the inbound data transfer charged?", options: ["Per GB transferred into AWS","It is free of charge","A flat monthly transfer fee","Per hour of network connection"], answer: 1, explanation: "Data transferred into AWS from the internet is free. You pay for data transferred out to the internet, and S3 still charges for storage and for requests such as uploads. Remember: data in is free, data out costs money.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-184", question: "Which of these AWS Free Tier offers is an Always Free monthly allowance that never expires?", options: ["Amazon RDS, 750 instance hours per month","Amazon EC2, 750 instance hours per month","AWS Lambda, 1 million requests per month","Amazon S3, 5 GB of Standard storage"], answer: 2, explanation: "AWS Lambda includes 1 million free requests and 400,000 GB-seconds of compute every month, with no end date. The EC2, RDS, and S3 allowances were 12-month offers under the old Free Tier. New accounts now cover those services with Free Tier credits instead.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-185", question: "A developer signs up for AWS on the free account plan to build a proof of concept. What happens when six months pass or the credits run out, whichever comes first?", options: ["The account automatically moves to the paid plan","Credits reset and a new six-month period begins","Usage continues at standard pay-as-you-go rates","The account closes unless it is upgraded to paid"], answer: 3, explanation: "The free account plan never charges you. When it ends, AWS closes the account and keeps your data for 90 days, during which you can upgrade to the paid plan to reopen it. There is no automatic upgrade and no surprise billing.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-186", question: "A company on the paid account plan has used up its Free Tier credits. Its AWS Lambda usage then goes beyond the always-free monthly allowance. What happens?", options: ["The extra usage is billed at standard pay-as-you-go rates","The functions are throttled until the next month begins","The account is suspended until the next billing cycle","AWS sends a warning email but never charges for it"], answer: 0, explanation: "On the paid plan, usage beyond the always-free allowances and any remaining credits is billed at normal pay-as-you-go rates. AWS does not throttle or suspend your resources to keep you free, so set up AWS Budgets alerts to avoid surprise bills.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-187", question: "A finance manager wants to see how the company's AWS spending changed over the last six months and forecast next month's costs. Which tool should they use?", options: ["AWS Pricing Calculator","AWS Cost Explorer","AWS Budgets","AWS Trusted Advisor"], answer: 1, explanation: "Cost Explorer visualizes historical costs and usage with filters and grouping, and forecasts future spending. AWS Budgets also uses forecasts, but its job is alerting when you cross a threshold, not exploring past trends. Pricing Calculator only estimates workloads you have not deployed yet.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-188", question: "A finance team needs the MOST detailed, line-item data about the company's AWS costs and usage, delivered to Amazon S3 for analysis with Amazon Athena. What should it use?", options: ["AWS Cost Explorer","AWS Budgets reports","AWS Cost and Usage Report","AWS Billing Dashboard"], answer: 2, explanation: "The Cost and Usage Report is the most granular billing data AWS provides, with hourly or daily line items delivered to an S3 bucket, where Amazon Athena can query it. Cost Explorer and the Billing Dashboard show summarized views, not every individual line item.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-189", question: "A small company needs around-the-clock phone, chat, and email access to AWS experts for production issues, at the LOWEST cost. Which support plan should it choose?", options: ["Basic Support","Developer Support","Enterprise Support","Business Support+"], answer: 3, explanation: "Business Support+ is the lowest-cost plan with around-the-clock phone, chat, and email access to AWS experts, and it replaces the classic Business plan. Developer Support offers only business-hours web and email access and ends on January 1, 2027. Enterprise also qualifies but costs far more.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-190", question: "A company on AWS Enterprise Support has a business-critical system down. What is the target initial response time for this support case?", options: ["Within 1 hour","Within 15 minutes","Within 5 minutes","Within 30 minutes"], answer: 1, explanation: "Enterprise Support targets a response within 15 minutes for business-critical system-down cases. Thirty minutes is the critical-case target for Business Support+, one hour is the target for production systems down, and five minutes is reserved for the Unified Operations plan.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-191", question: "A company on Basic Support can see only a few AWS Trusted Advisor checks. It wants the full set, including cost optimization checks, at the LOWEST cost. What should it do?", options: ["Upgrade to Business Support+","Upgrade to Developer Support","Upgrade to Enterprise Support","Buy a separate Trusted Advisor subscription"], answer: 0, explanation: "Basic and Developer Support include only core Trusted Advisor checks: all service limits checks plus a few security and fault tolerance checks. Business Support+ is the lowest-cost plan that unlocks every check. Enterprise also does but costs more, and Trusted Advisor is never sold separately.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-192", question: "An enterprise wants a dedicated team of AWS billing and account experts to help resolve invoice and account questions quickly. Which AWS offering provides this?", options: ["AWS Professional Services","A Technical Account Manager","AWS Partner Network consultants","The AWS Concierge Support team"], answer: 3, explanation: "The Concierge Support team is a group of billing and account specialists included with Enterprise Support. A Technical Account Manager is tempting, but a TAM focuses on technical and architectural guidance, not invoices and account administration.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-193", question: "A company has 30 AWS accounts. It wants to manage them centrally, apply guardrail policies to groups of accounts, and pay a single bill. Which service should it use?", options: ["AWS IAM Identity Center","AWS Resource Access Manager","AWS Organizations","AWS Service Catalog"], answer: 2, explanation: "AWS Organizations groups accounts into organizational units, applies service control policies, and provides consolidated billing with one bill. IAM Identity Center is tempting because it spans accounts, but it only manages workforce sign-in and permissions, not guardrail policies or billing.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-194", question: "A company wants to apply the same service control policy to all of its development accounts at once. What should it create in AWS Organizations?", options: ["An IAM group","An organizational unit","A cost allocation tag","A resource group"], answer: 1, explanation: "An organizational unit, or OU, groups accounts inside an organization. A service control policy attached to an OU applies to every account in it, such as all development accounts. An IAM group is tempting, but it groups users inside one account, not accounts.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-195", question: "Amazon S3 charges less per GB as a company stores more data each month. Which AWS pricing principle does this illustrate?", options: ["Pay less by using more","Pay as you go","Save when you commit","Pay less as AWS grows"], answer: 0, explanation: "Pay less by using more means tiered, volume-based pricing: the per-unit price drops as your usage grows, as with S3 storage and data transfer out. Pay less as AWS grows is different; it describes AWS cutting prices over time thanks to economies of scale.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-196", question: "A company is reviewing its AWS data transfer bill. Which traffic pattern incurs a data transfer charge?", options: ["Data coming in from the internet to an EC2 instance","Data between EC2 and Amazon S3 in the same Region","Data between instances in one AZ using private IPs","Data between instances in different AZs in one Region"], answer: 3, explanation: "Traffic between Availability Zones in the same Region is charged per GB in each direction. Inbound internet traffic is free, as is traffic between EC2 and S3 in the same Region and private IP traffic within one Availability Zone. Remember: cross-AZ traffic costs money.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-197", question: "A company runs large batch processing jobs at unpredictable times. The jobs can be stopped and restarted without problems. Which EC2 purchasing option is MOST cost-effective?", options: ["On-Demand Instances","Reserved Instances","Spot Instances","Dedicated Hosts"], answer: 2, explanation: "Spot Instances use spare EC2 capacity at up to 90 percent off On-Demand prices, ideal for fault-tolerant, interruptible work like batch jobs. Reserved Instances need a steady, predictable workload and a one or three-year commitment, which does not fit unpredictable jobs.", domain: "domain4", section: "clf-05" },
  { id: "clf-q-198", question: "A company wants discounted compute pricing for the next 3 years but expects to change instance families, move between Regions, and adopt AWS Fargate. Which option offers the MOST flexibility?", options: ["Standard Reserved Instances","Convertible Reserved Instances","EC2 Instance Savings Plans","Compute Savings Plans"], answer: 3, explanation: "Compute Savings Plans commit to a steady amount of compute spend per hour and apply automatically across instance families, sizes, Regions, and even Fargate and Lambda. Convertible Reserved Instances allow some exchanges but cover only EC2, and EC2 Instance Savings Plans lock you to one family in one Region.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-199", question: "A company is moving a database to AWS and wants to bring its existing license, which is priced per physical CPU socket and core. Which EC2 option should it use?", options: ["Dedicated Instances","Spot Instances","Dedicated Hosts","On-Demand Instances"], answer: 2, explanation: "Dedicated Hosts give you a whole physical server with visibility into its sockets and cores, which bring-your-own-license software often requires. Dedicated Instances also run on single-tenant hardware, but you cannot see or control the physical host, so they do not meet per-socket licensing rules.", domain: "domain4", section: "clf-05" },
  { id: "clf-q-200", question: "A company wants machine learning based recommendations for the best EC2 instance types and sizes, based on each workload's actual CPU and memory use. Which service should it use?", options: ["AWS Trusted Advisor","AWS Pricing Calculator","AWS Budgets","AWS Compute Optimizer"], answer: 3, explanation: "Compute Optimizer uses machine learning on utilization metrics to recommend optimal EC2 instance types, and also covers Auto Scaling groups, EBS volumes, and Lambda functions. Trusted Advisor is tempting, but it runs broad best-practice checks, while Compute Optimizer is built for detailed right-sizing recommendations.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-201", question: "An independent software vendor wants AWS customers to find, buy, and launch its product, with the charges appearing on the customers' AWS bills. Where should the vendor list it?", options: ["AWS Service Catalog","AWS Professional Services","AWS Marketplace","AWS Artifact"], answer: 2, explanation: "AWS Marketplace is a curated digital catalog where vendors sell software, data, and services that customers deploy on AWS and pay for through their AWS bill. Service Catalog is tempting, but it is an internal catalog an organization uses to offer its own approved products to its users.", domain: "domain4", section: "clf-21" },
  { id: "clf-q-202", question: "A company is estimating its Amazon S3 bill. Which set of factors does Amazon S3 charge for?", options: ["A monthly fee per bucket plus GB stored","GB stored, requests, and data transferred out","Provisioned capacity per hour and data in","Number of users and number of buckets"], answer: 1, explanation: "S3 bills for the GB stored each month, which varies by storage class, for requests and retrievals, and for data transferred out. There is no charge per bucket or per user, and data transferred in from the internet is free.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-203", question: "A company is moving a small API to AWS Lambda and wants to understand the bill. How is Lambda priced?", options: ["By number of requests and compute duration","By instance hours, even when the function is idle","By a flat monthly fee for each function","By the number of users who call the function"], answer: 0, explanation: "Lambda charges per request and for compute duration, measured in GB-seconds based on the memory you allocate. You pay nothing while functions sit idle, and the always-free allowance covers 1 million requests and 400,000 GB-seconds each month. Instance-hour billing applies to EC2, not Lambda.", domain: "domain4", section: "clf-10" },
  { id: "clf-q-204", question: "Several projects share one AWS account. The finance team wants each month's costs broken down by project and department. What should the company use?", options: ["AWS Budgets","Consolidated billing","AWS Pricing Calculator","Cost allocation tags"], answer: 3, explanation: "Cost allocation tags are key-value labels on resources, such as Project or Department. Once activated in the Billing console, costs can be grouped by tag in Cost Explorer and the Cost and Usage Report. Consolidated billing splits costs by account, which does not help when projects share one account.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-205", question: "A company's development EC2 instances run 24 hours a day but are used only about 40 hours per week. It wants to cut costs without any long-term commitment. Which action is MOST cost-effective?", options: ["Buy Reserved Instances covering all of them","Move them to a cheaper AWS Region instead","Schedule them to stop outside work hours","Run them on Dedicated Hosts instead of shared"], answer: 2, explanation: "You pay nothing for compute while an EC2 instance is stopped, so scheduling dev instances to stop outside work hours removes most of their cost, though attached EBS storage is still billed. Reserved Instances also lower rates, but they need a one or three-year commitment and assume constant use.", domain: "domain4", section: "clf-21" },
  { id: "clf-q-206", question: "A company wants a data-driven business case that compares the cost of its current on-premises servers with running them on AWS. Which AWS service should it use?", options: ["AWS Cost Explorer","AWS Migration Evaluator","AWS Application Discovery Service","AWS Application Migration Service"], answer: 1, explanation: "Migration Evaluator, formerly TSO Logic, analyzes your on-premises inventory and utilization and builds a business case projecting AWS costs. It replaces the retired TCO Calculator. Application Discovery Service also collects server data, but it is for migration planning, not cost comparison.", domain: "domain4", section: "clf-20" },
  { id: "clf-q-207", question: "A new startup wants AWS support that costs nothing extra. Which support plan is included with every AWS account at no charge?", options: ["Basic Support","Enterprise Support","Business Support+","Developer Support"], answer: 0, explanation: "Basic Support is free for every account. It includes customer service for account and billing questions, documentation, AWS re:Post, the AWS Health Dashboard, and core Trusted Advisor checks. It does not include technical support cases; for those you need a paid plan such as Business Support+.", domain: "domain4", section: "clf-18" },
  { id: "clf-q-208", question: "A company's application logs in Amazon S3 are read often for 30 days, then only a few times a month. Older logs must still open in milliseconds, and the data must survive the loss of an Availability Zone. What is the MOST cost-effective approach?", options: ["A Lifecycle rule moving logs to S3 One Zone-IA after 30 days","A Lifecycle rule moving logs to S3 Standard-IA after 30 days","A Lifecycle rule moving logs to Glacier Deep Archive after 30 days","Keeping every log in S3 Standard with versioning enabled"], answer: 1, explanation: "S3 Standard-IA costs less to store than Standard, keeps millisecond access, and stores data across multiple Availability Zones. One Zone-IA is tempting because it is cheaper, but it keeps data in a single zone, failing the resilience need. Glacier Deep Archive needs hours to restore.", domain: "domain4", section: "clf-08" },
  { id: "clf-q-209", question: "A developer on the Basic Support plan has a technical question about configuring Amazon S3. Where can the developer get answers from the AWS community and AWS experts at no extra cost?", options: ["AWS re:Post","A technical support case","AWS Trusted Advisor","AWS Health Dashboard"], answer: 0, explanation: "AWS re:Post is a free, community-driven question and answer service where AWS experts and community members answer technical questions. Opening a technical support case is tempting, but Basic Support covers only account and billing cases, so technical cases need a paid plan. Trusted Advisor runs automated account checks instead.", domain: "domain4", section: "clf-21" },
  { id: "clf-q-210", question: "An EC2 instance averages 5 percent CPU utilization. The company wants to lower its cost without hurting performance. What should it do FIRST?", options: ["Right-size it to a smaller instance type","Buy a Reserved Instance for its current size","Move it to a Dedicated Host","Place it behind an Application Load Balancer"], answer: 0, explanation: "Right-sizing means matching instance type and size to actual workload needs, so you stop paying for idle capacity. Always right-size before buying Reserved Instances or Savings Plans; otherwise you lock in a discount on an oversized instance for years.", domain: "domain4", section: "clf-21" },
  { id: "clf-q-211", question: "An operations team wants alerts about AWS service issues and scheduled maintenance that affect its own resources, such as an EC2 instance scheduled for retirement. Which service should it use?", options: ["AWS Trusted Advisor","AWS Health Dashboard","Amazon CloudWatch","AWS CloudTrail"], answer: 1, explanation: "The AWS Health Dashboard, formerly the Personal Health Dashboard, gives a personalized view of AWS events affecting your account, including scheduled maintenance and instance retirements. CloudWatch is tempting, but it monitors your own metrics and logs, not AWS-side service events.", domain: "domain4", section: "clf-14" },
  { id: "clf-q-212", question: "A company is migrating an on-premises application that uses Apache ActiveMQ and the AMQP and MQTT protocols. It wants a managed message broker on AWS without rewriting its messaging code. Which service should it use?", options: ["Amazon MQ","Amazon SQS","Amazon SNS","Amazon Kinesis Data Streams"], answer: 0, explanation: "Amazon MQ is a managed broker for ActiveMQ and RabbitMQ that supports open protocols such as AMQP and MQTT, so existing code keeps working. SQS is tempting, but it uses its own AWS API, so the application would need to be rewritten.", domain: "domain3", section: "clf-13" },
  { id: "clf-q-213", question: "A delivery company wants to send SMS text messages and mobile push notifications to customers whenever a package changes status. Which service should it use?", options: ["Amazon SQS","Amazon SNS","Amazon SES","Amazon MQ"], answer: 1, explanation: "Amazon SNS is a publish and subscribe service that can push notifications to SMS, mobile push, email, Lambda, and SQS subscribers. Amazon SES is tempting, but it handles email only, not text messages or mobile push notifications.", domain: "domain3", section: "clf-13" },
  { id: "clf-q-214", question: "Worker EC2 instances read orders from an Amazon SQS queue. During busy periods the queue grows long and orders are delayed. The company wants more workers added automatically when the backlog grows. What should it do?", options: ["Increase the message retention period of the queue","Replace the queue with an Amazon SNS topic","Scale an Auto Scaling group on the queue length","Move the workers to a larger instance type"], answer: 2, explanation: "An Auto Scaling group can scale out based on the CloudWatch metric for the number of messages waiting in the queue, adding workers as the backlog grows. A larger instance type is vertical scaling, which is manual and limited, and does not react to the queue automatically.", domain: "domain3", section: "clf-13" },
  { id: "clf-q-215", question: "A development team wants to define its AWS infrastructure using Python and TypeScript, the languages it already uses, and have the result deployed as a CloudFormation stack. Which service should it use?", options: ["AWS Elastic Beanstalk","AWS CodeDeploy","AWS Serverless Application Model","AWS Cloud Development Kit"], answer: 3, explanation: "The AWS CDK lets developers write infrastructure in familiar programming languages and synthesizes it into a CloudFormation template. The Serverless Application Model is tempting because it also deploys through CloudFormation, but it uses YAML or JSON templates, not Python or TypeScript code.", domain: "domain3", section: "clf-11" },
  { id: "clf-q-216", question: "A company wants to automatically roll out new versions of its application to 50 EC2 instances and 30 on-premises servers from one service. Which service should it use?", options: ["AWS CodeDeploy","AWS Elastic Beanstalk","AWS CodeBuild","AWS CodeArtifact"], answer: 0, explanation: "AWS CodeDeploy automates application deployments to EC2 instances and to on-premises servers running the CodeDeploy agent, so it covers the hybrid fleet. Elastic Beanstalk is tempting, but it deploys only into environments it creates in AWS, not onto existing on-premises servers.", domain: "domain3", section: "clf-11" },
  { id: "clf-q-217", question: "Developers download npm, Maven, and pip dependencies directly from the public internet. The company wants a managed, central place to store and share approved software packages with its build tools. Which service should it use?", options: ["AWS CodeBuild","AWS CodeArtifact","Amazon Elastic Container Registry","AWS CodePipeline"], answer: 1, explanation: "AWS CodeArtifact is a managed artifact repository that stores and shares software packages and works with npm, Maven, pip, and other package managers. Elastic Container Registry is tempting, but it stores container images, not language packages and libraries.", domain: "domain3", section: "clf-11" },
  { id: "clf-q-218", question: "A company is launching a mobile app for millions of consumers. Users must be able to sign up and sign in with an email address or with their existing Google or Facebook accounts. Which service should the company use?", options: ["An IAM user for each customer","AWS IAM Identity Center","Amazon Cognito","AWS Directory Service"], answer: 2, explanation: "Amazon Cognito provides sign-up, sign-in, and social identity login for web and mobile app users and scales to millions of users. IAM Identity Center is tempting, but it is for workforce single sign-on to AWS accounts and business applications, not for public app customers.", domain: "domain2", section: "clf-19" },
  { id: "clf-q-219", question: "A company runs Windows applications on EC2 that must join a Microsoft Active Directory domain. It wants AWS to manage the domain controllers and to set up a trust with its on-premises Active Directory. Which service should it use?", options: ["Amazon Cognito","AWS Security Token Service","AWS IAM Identity Center","AWS Directory Service"], answer: 3, explanation: "AWS Managed Microsoft AD, part of AWS Directory Service, runs real Active Directory domain controllers in AWS and supports trusts with on-premises Active Directory. IAM Identity Center is tempting, but it provides single sign-on and cannot act as a domain that Windows servers join.", domain: "domain2", section: "clf-19" },
  { id: "clf-q-220", question: "Users in Asia and Australia upload large video files to a single S3 bucket in a United States Region, and uploads are slow. The company wants faster uploads to the same bucket by routing them through nearby edge locations. What should it use?", options: ["S3 Transfer Acceleration","AWS Global Accelerator","S3 Cross-Region Replication","AWS Direct Connect"], answer: 0, explanation: "S3 Transfer Acceleration sends uploads to the nearest edge location, then carries them over the fast AWS network to the bucket. Global Accelerator is tempting, but it fronts load balancers, EC2 instances, and IP addresses, not S3 buckets. Cross-Region Replication copies objects after they arrive, so it cannot speed up uploads.", domain: "domain3", section: "clf-12" },
  { id: "clf-q-221", question: "A film studio in a large city needs single-digit millisecond latency to EC2 instances for video rendering, but the nearest AWS Region is far away. It does not want to install any AWS hardware in its own building. What should it use?", options: ["AWS Outposts","AWS Local Zones","AWS Wavelength","Amazon CloudFront"], answer: 1, explanation: "Local Zones place AWS compute and storage in large metro areas, close to users, and are run by AWS in its own facilities. Outposts is tempting, but it puts AWS racks inside the customer building, which the studio wants to avoid. Wavelength targets 5G mobile devices.", domain: "domain3", section: "clf-12" },
  { id: "clf-q-222", question: "A company wants to automatically build a golden Amazon Machine Image every week with the latest operating system patches, run tests against it, and share it to other Regions. Which service should it use?", options: ["AWS Backup","AWS Systems Manager Patch Manager","EC2 Image Builder","AWS Elastic Beanstalk"], answer: 2, explanation: "EC2 Image Builder automates creating, patching, testing, and distributing AMIs on a schedule, and it is free apart from the underlying resources. Patch Manager is tempting, but it patches instances that are already running; it does not build, test, and distribute new images.", domain: "domain3", section: "clf-06" },
  { id: "clf-q-223", question: "Under the AWS Shared Responsibility Model, which task is the customer's responsibility for its Amazon EBS volumes?", options: ["Replicating volume data within the Availability Zone","Replacing failed storage hardware in the data center","Securing physical access to the storage servers","Scheduling snapshot backups and turning on encryption"], answer: 3, explanation: "Customers own their data, so they must set up snapshot backups and choose to encrypt their volumes. AWS handles the infrastructure: replicating EBS data within the Availability Zone, replacing failed hardware, and protecting the physical data centers.", domain: "domain2", section: "clf-06" },
];

